// Self-contained chrome styling for the standalone `Editor`
// (`editor/components/internal/EditorStandaloneChrome.ts`) — the editor
// toolbar, the `⋮` tools menu, and the Custom Dictionary dialog that reproduce
// the app's editor panel (`gep`) without the app shell or Bootstrap.
//
// The panel rules are the SAME source the app pages use
// (`_editor-panel-chrome.scss` + `_preview-panel-chrome.scss`, included nested
// so they scope to this panel); this file only adds what a bare embed needs on
// top: the panel identity, the surface layout inside the panel body, inline-SVG
// icon sizing, the status line, the dictionary dialog, and the minimal
// Bootstrap primitives (`.btn`, `.form-switch`, `.visually-hidden`) a page
// without Bootstrap lacks. Everything lives under `.ol-standalone-editor`, so
// this sheet never leaks button/menu rules onto a host page.
//
// The base theme tokens it consumes (`--surface`, `--accent`, …) are injected
// separately by the component in standalone mode (`theme-vars-styles.ts`).

@use '../../styles/editor-panel-chrome' as *;
@use '../../styles/invisible-character-highlight' as *;
@use '../../styles/preview-panel-chrome' as *;
@use '../../styles/standalone-bootstrap-shim' as *;

.ol-standalone-editor {
  display: flex;
  flex-direction: column;
  min-height: 0;
  height: 100%;
  border: 1px solid var(--line);
  border-radius: 0.75rem;
  background: var(--surface);
  overflow: hidden;
  box-shadow: var(--shadow);
  color: var(--ink);

  // Shared app chrome, scoped to this panel by the nesting. The include order
  // mirrors `shell.scss`: the toolbar shell, then the preview chrome whose
  // action-button rules the menu buttons override, then the menu/body rules.
  @include ol-editor-panel-chrome-base;
  @include ol-preview-panel-chrome;
  @include ol-editor-panel-chrome-menu;
  @include ol-standalone-bootstrap-shim;

  // Invisible-character decorations (`scripts/invisible-characters.ts`) drawn
  // inside this panel's Monaco instance.
  @include ol-invisible-character-highlight;

  // The chrome draws its icons as inline SVG (the app uses the bootstrap-icons
  // webfont via `.bi`), so size the SVG off the icon box.
  .topbar-icon-btn__icon svg {
    width: 1em;
    height: 1em;
    display: block;
  }

  // The component-owned root sits inside the panel body and carries the
  // surfaces (Monaco host + the simple-editor textarea).
  .ol-editor-root {
    display: flex;
    flex: 1 1 auto;
    min-width: 0;
    min-height: 0;
    position: relative;
  }

  .ol-editor-surface {
    flex: 1 1 auto;
    min-width: 0;
  }

  .ol-editor-surface[hidden],
  .ol-editor-simple-input[hidden] {
    display: none !important;
  }

  .editor-panel__status {
    flex: 0 0 auto;
    margin: 0;
    padding: 0.28rem 0.65rem;
    border-top: 1px solid var(--line);
    background: var(--surface-elevated, var(--surface));
    color: var(--muted);
    font-size: 0.76rem;
  }

  // --- Custom Dictionary dialog -------------------------------------------
  .ol-editor-dictionary-dialog {
    width: min(30rem, calc(100vw - 2rem));
    max-height: min(38rem, calc(100vh - 3rem));
    padding: 0;
    border: 1px solid var(--line);
    border-radius: 0.9rem;
    background: var(--surface);
    color: var(--ink);
    overflow: auto;
  }

  .ol-editor-dictionary-dialog::backdrop {
    background: rgba(15, 17, 21, 0.55);
  }

  .ol-editor-dictionary-dialog__form {
    display: grid;
    gap: 0.85rem;
    padding: 1rem 1.1rem 1.15rem;
  }

  .ol-editor-dictionary-dialog__header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 0.75rem;
  }

  .ol-editor-dictionary-dialog__title {
    margin: 0;
    color: var(--heading);
    font-size: 1.02rem;
    font-weight: 700;
  }

  .ol-editor-dictionary-dialog__subtitle {
    margin: 0.2rem 0 0;
    color: var(--muted);
    font-size: 0.8rem;
  }

  .ol-editor-dictionary-dialog__language {
    display: grid;
    gap: 0.28rem;
    color: var(--muted);
    font-size: 0.78rem;
    font-weight: 600;
  }

  .ol-editor-dictionary-dialog__group {
    display: grid;
    gap: 0.45rem;
    padding-top: 0.55rem;
    border-top: 1px solid color-mix(in srgb, var(--line) 82%, transparent);
  }

  .ol-editor-dictionary-dialog__group-title {
    margin: 0;
    color: var(--heading);
    font-size: 0.86rem;
    font-weight: 700;
  }

  .ol-editor-dictionary-dialog__add {
    display: flex;
    align-items: center;
    gap: 0.4rem;
  }

  .ol-editor-dictionary-dialog__add input,
  .ol-editor-dictionary-dialog__language select {
    flex: 1 1 auto;
    min-width: 0;
    padding: 0.32rem 0.5rem;
    border: 1px solid var(--line);
    border-radius: 0.55rem;
    background: var(--preview-code-bg);
    color: var(--ink);
    font: inherit;
    font-size: 0.85rem;
  }

  .ol-editor-dictionary-dialog__add input:focus-visible,
  .ol-editor-dictionary-dialog__language select:focus-visible {
    outline: none;
    box-shadow: 0 0 0 3px var(--accent-halo);
  }

  .ol-editor-dictionary-dialog__list {
    display: flex;
    flex-wrap: wrap;
    gap: 0.32rem;
  }

  .ol-editor-dictionary-dialog__empty {
    margin: 0;
    color: var(--muted);
    font-size: 0.8rem;
  }

  .ol-editor-dictionary-dialog__entry {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    padding: 0.16rem 0.3rem 0.16rem 0.55rem;
    border: 1px solid var(--line);
    border-radius: 999px;
    background: var(--preview-code-bg);
    font-size: 0.82rem;
  }

  .ol-editor-dictionary-dialog__remove {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 1.1rem;
    height: 1.1rem;
    padding: 0;
    border: 0;
    border-radius: 50%;
    background: transparent;
    color: var(--muted);
    font-size: 0.9rem;
    line-height: 1;
    cursor: pointer;
  }

  .ol-editor-dictionary-dialog__remove:hover {
    color: var(--accent);
    background: var(--theme-toggle-hover-bg);
  }

  .ol-editor-dictionary-dialog__actions {
    display: flex;
    flex-wrap: wrap;
    justify-content: flex-end;
    gap: 0.4rem;
  }
}

// Dark-mode menu elevation, matching the app shell. Keyed off the component's
// own `[data-ol-theme]` marker rather than the page's `<html data-theme>`, so a
// light embed inside a dark page keeps the light elevation (and vice versa).
// Written unnested because the marker sits on the host container, above the
// panel scope.
[data-ol-theme='dark'] .ol-standalone-editor .editor-panel__options-menu {
  box-shadow:
    0 0.2rem 0.55rem rgba(0, 0, 0, 0.22),
    0 0.85rem 1.9rem rgba(0, 0, 0, 0.38);
}

// The darker warning tint for multi-character runs, same trigger as above.
[data-ol-theme='dark'] .ol-standalone-editor {
  @include ol-invisible-character-highlight-dark;
}
