import { refs, state } from '../../../../scripts/shared.ts';

function applyOpenLyricPreviewControllerMenuMethods(PreviewControllerClass) {
  Object.assign(PreviewControllerClass.prototype, {
    isOpenLyricOptionsElement(this: any, element) {
      return (
        element instanceof Element &&
        Boolean(refs.openLyricOptions?.contains(element))
      );
    },

    closeOpenLyricOptionsMenu(this: any) {
      if (refs.openLyricOptions) {
        refs.openLyricOptions.dataset.open = 'false';
      }

      if (refs.openLyricOptionsBtn) {
        refs.openLyricOptionsBtn.setAttribute('aria-expanded', 'false');
      }

      if (refs.openLyricOptionsMenu) {
        refs.openLyricOptionsMenu.hidden = true;
      }
    },

    openOpenLyricOptionsMenu(this: any) {
      if (
        !state.openLyricPluginAvailable ||
        !refs.openLyricOptionsBtn ||
        !refs.openLyricOptionsMenu
      ) {
        return;
      }

      this.syncOpenLyricClipboardActionAvailability?.();

      if (refs.openLyricOptions) {
        refs.openLyricOptions.dataset.open = 'true';
      }

      refs.openLyricOptionsBtn.setAttribute('aria-expanded', 'true');
      refs.openLyricOptionsMenu.hidden = false;
    },

    handleOpenLyricOptionsToggleClick(this: any, event) {
      event.preventDefault();

      const wasExpanded =
        refs.openLyricOptionsBtn?.getAttribute('aria-expanded') === 'true' &&
        Boolean(refs.openLyricOptionsMenu && !refs.openLyricOptionsMenu.hidden);

      if (wasExpanded) {
        this.closeOpenLyricOptionsMenu();
        return;
      }

      this.closeDeclarePartMenus();
      this.openOpenLyricOptionsMenu();
    },

    handleOpenLyricOptionsFocusOut(this: any, event) {
      const nextFocusTarget = event.relatedTarget;

      if (
        nextFocusTarget instanceof Node &&
        refs.openLyricOptions?.contains(nextFocusTarget)
      ) {
        return;
      }

      globalThis.queueMicrotask(() => {
        const activeElement = document.activeElement;

        if (
          activeElement instanceof Node &&
          refs.openLyricOptions?.contains(activeElement)
        ) {
          return;
        }

        this.closeOpenLyricOptionsMenu();
      });
    },

    handleOpenLyricImageDownloadClick(this: any) {
      this.closeOpenLyricOptionsMenu();
      void this.downloadOpenLyricPreviewAsJpeg();
    },

    handleOpenLyricPowerPointDownloadClick(this: any) {
      this.closeOpenLyricOptionsMenu();
      void this.downloadOpenLyricPresentationAsPowerPoint();
    },

    handleOpenLyricTextCopyClick(this: any) {
      this.closeOpenLyricOptionsMenu();
      void this.copyOpenLyricPreviewAsText();
    },

    handleOpenLyricPrintClick(this: any) {
      this.closeOpenLyricOptionsMenu();
      this.printOpenLyricPreview();
    },
  });
}

export { applyOpenLyricPreviewControllerMenuMethods };
