import { getDefaultDraftExample } from '../default-draft-example.ts';
import { applyDocumentControllerContentMethods } from './document-controllers/document-content.ts';
import { applyDocumentControllerRawTextImportMethods } from './document-controllers/raw-text-import.ts';
import { applyDocumentControllerResetExampleMethods } from './document-controllers/reset-examples.ts';
import { applyDocumentControllerShareLinkMethods } from './document-controllers/share-links.ts';
import { applyDocumentControllerShareQrMethods } from './document-controllers/share-qr.ts';
import { applyDocumentControllerShareUiMethods } from './document-controllers/share-ui.ts';

/**
 * Manages the active markdown document: file open/save flows, draft recovery,
 * resets, and dirty-state persistence.
 */
class DocumentController {
  [key: string]: any;

  constructor({ preferences, previewController }) {
    this.preferences = preferences;
    this.previewController = previewController;
    this.shareCopyButtonResetTimer = 0;
    this.shareLinkRefreshTimer = 0;
    this.shareLinkGenerationRequestId = 0;
    this.shareLinkQrRenderRequestId = 0;
    this.shareLinkQrFullscreenRenderRequestId = 0;
    this.activeShareQrDescriptor = null;
    this.shareQrFullscreenChunkIndex = null;
    this.shareQrPreviewTrigger = null;
    this.sharedLinkPasswordResolver = null;
    this.sharedLinkPasswordValue = null;
    this.sharedLinkPasswordEventsBound = false;
    this.pendingProgrammaticDocument = null;
    this.selectedResetExampleId = getDefaultDraftExample().id;

    this.handleFileInputChange = this.handleFileInputChange.bind(this);
    this.handleResetExampleDialogClose =
      this.handleResetExampleDialogClose.bind(this);
    this.handleResetExampleSelectionChange =
      this.handleResetExampleSelectionChange.bind(this);
    this.handleRawTextImportDialogClose =
      this.handleRawTextImportDialogClose.bind(this);
    this.handleRawTextImportSubmit = this.handleRawTextImportSubmit.bind(this);
    this.loadSelectedResetExample = this.loadSelectedResetExample.bind(this);
    this.handleShareDialogClose = this.handleShareDialogClose.bind(this);
    this.handleShareEncryptionInput =
      this.handleShareEncryptionInput.bind(this);
    this.handleShareOutputModeChange =
      this.handleShareOutputModeChange.bind(this);
    this.handleShareQrTextChunkLengthChange =
      this.handleShareQrTextChunkLengthChange.bind(this);
    this.handleShareQrFullscreenDialogClose =
      this.handleShareQrFullscreenDialogClose.bind(this);
    this.handleShareQrPreviewActivate =
      this.handleShareQrPreviewActivate.bind(this);
    this.handleShareEncryptionToggleChange =
      this.handleShareEncryptionToggleChange.bind(this);
    this.handleSharedLinkPasswordCancel =
      this.handleSharedLinkPasswordCancel.bind(this);
    this.handleSharedLinkPasswordDialogClose =
      this.handleSharedLinkPasswordDialogClose.bind(this);
    this.handleSharedLinkPasswordSubmit =
      this.handleSharedLinkPasswordSubmit.bind(this);

    this.ensureSharedLinkPasswordDialogBindings();
  }
}

applyDocumentControllerContentMethods(DocumentController);
applyDocumentControllerRawTextImportMethods(DocumentController);
applyDocumentControllerResetExampleMethods(DocumentController);
applyDocumentControllerShareUiMethods(DocumentController);
applyDocumentControllerShareQrMethods(DocumentController);
applyDocumentControllerShareLinkMethods(DocumentController);

export { DocumentController };
