function createOpenLyricMonacoTheme(base, rules, colors) {
  return {
    base,
    inherit: true,
    rules,
    colors,
  };
}

function defineOpenLyricMonacoThemes(
  monacoEditor,
  { lightRules = [], darkRules = [] } = {},
) {
  monacoEditor.defineTheme(
    LANGUAGE_THEME,
    createOpenLyricMonacoTheme('vs', lightRules, OPEN_LYRIC_LIGHT_THEME_COLORS),
  );
  monacoEditor.defineTheme(
    DARK_LANGUAGE_THEME,
    createOpenLyricMonacoTheme(
      'vs-dark',
      darkRules,
      OPEN_LYRIC_DARK_THEME_COLORS,
    ),
  );
}

export { defineOpenLyricMonacoThemes };
