import { refs, state } from '../shared.ts';
import { hideChordDiagramPopup } from '../../plugins/OpenLyric/chord-popup.ts';

const MIN_EDITOR_PANEL_WIDTH_PX = 280;
const MIN_PREVIEW_PANEL_WIDTH_PX = 240;
const RESIZE_KEYBOARD_STEP_PERCENT = 5;
const RESIZE_HANDLE_WIDTH_FALLBACK_PX = 16;
const PANEL_HIDE_POINTER_THRESHOLD_PX = 32;
const STACKED_LAYOUT_MEDIA_QUERY = '(max-width: 992px)';

/**
 * Owns shell presentation: visible panels, persisted widths, resize handles,
 * and editor relayout after the shell changes.
 */
class ShellLayoutController {
  constructor({
    preferences,
    onOpenLyricEnableRequest = null,
    onPanelVisibilityChange = null,
  }) {
    this.preferences = preferences;
    this.onOpenLyricEnableRequest = onOpenLyricEnableRequest;
    this.onPanelVisibilityChange = onPanelVisibilityChange;
    this.activePanelResize = null;
    this.scheduledShellLayoutFrame = 0;
    this.topbarMetaMobileState = null;

    this.handlePanelResizePointerDown =
      this.handlePanelResizePointerDown.bind(this);
    this.handlePanelResizePointerMove =
      this.handlePanelResizePointerMove.bind(this);
    this.handlePanelResizePointerUp =
      this.handlePanelResizePointerUp.bind(this);
    this.handlePanelResizePointerCancel =
      this.handlePanelResizePointerCancel.bind(this);
    this.handlePanelResizeLostPointerCapture =
      this.handlePanelResizeLostPointerCapture.bind(this);
    this.handlePanelResizeKeydown = this.handlePanelResizeKeydown.bind(this);
    this.handlePanelResizeDoubleClick =
      this.handlePanelResizeDoubleClick.bind(this);
  }

  loadPreferences() {
    const savedPanelVisibility = this.hasSupplementalShellPanels()
      ? this.preferences.loadPanelVisibilityPreference()
      : null;

    this.applyPanelVisibilityPreference(savedPanelVisibility);

    state.panelSizeWeights =
      this.preferences.loadPanelSizePreference() ??
      this.preferences.normalizePanelSizeWeights(null);

    this.getEffectivePanelVisibility();
  }

  bindEvents() {
    refs.toggleEditorBtn?.addEventListener('click', () => {
      this.toggleEditor();
    });
    refs.togglePreviewBtn?.addEventListener('click', () => {
      this.togglePreview();
    });
    refs.toggleOpenLyricBtn?.addEventListener('click', () => {
      if (!this.isOpenLyricPanelAvailable()) {
        this.onOpenLyricEnableRequest?.();
        return;
      }

      this.toggleOpenLyric();
    });
  }

  isOpenLyricPanelAvailable() {
    return Boolean(state.openLyricPluginAvailable);
  }

  hasSupplementalShellPanels() {
    return Boolean(refs.previewPanel || refs.openLyricPanel);
  }

  getEffectivePanelVisibility() {
    const hasEditorPanel = Boolean(refs.editorPanel);
    const hasPreviewPanel = Boolean(refs.previewPanel);
    const hasOpenLyricPanel = Boolean(refs.openLyricPanel);

    if (!hasEditorPanel) {
      state.editorVisible = false;
    }

    if (!hasPreviewPanel) {
      state.previewVisible = false;
    }

    if (!hasOpenLyricPanel) {
      state.openLyricVisible = false;
    }

    let editorVisible = hasEditorPanel && state.editorVisible;
    let previewVisible = hasPreviewPanel && state.previewVisible;
    let openLyricVisible =
      hasOpenLyricPanel &&
      this.isOpenLyricPanelAvailable() &&
      state.openLyricVisible;

    if (!editorVisible && !previewVisible && !openLyricVisible) {
      if (hasPreviewPanel) {
        state.previewVisible = true;
        previewVisible = true;
      } else if (hasEditorPanel) {
        state.editorVisible = true;
        editorVisible = true;
      } else if (hasOpenLyricPanel && this.isOpenLyricPanelAvailable()) {
        state.openLyricVisible = true;
        openLyricVisible = true;
      }
    }

    return {
      editorVisible,
      previewVisible,
      openLyricVisible,
    };
  }

  getPanelDefinitions() {
    return [
      {
        key: 'editor',
        label: 'Editor',
        minWidth: MIN_EDITOR_PANEL_WIDTH_PX,
        isVisible: () => state.editorVisible,
        getElement: () => refs.editorPanel,
      },
      {
        key: 'preview',
        label: 'Preview',
        minWidth: MIN_PREVIEW_PANEL_WIDTH_PX,
        isVisible: () => state.previewVisible,
        getElement: () => refs.previewPanel,
      },
      {
        key: 'openLyric',
        label: 'Open Lyric Preview',
        minWidth: MIN_PREVIEW_PANEL_WIDTH_PX,
        isVisible: () =>
          this.isOpenLyricPanelAvailable() && state.openLyricVisible,
        getElement: () => refs.openLyricPanel,
      },
    ];
  }

  scheduleEditorLayout() {
    if (this.scheduledShellLayoutFrame) {
      return;
    }

    this.scheduledShellLayoutFrame = globalThis.requestAnimationFrame(() => {
      this.scheduledShellLayoutFrame = 0;
      this.applyPanelSizePreference();
      this.updatePanelResizeHandles();

      if (
        state.editor &&
        state.editorVisible &&
        state.editorMode === 'monaco'
      ) {
        state.editor.layout();
      }
    });
  }

  handleViewportResize() {
    if (this.activePanelResize) {
      this.stopPanelResize();
    }

    this.syncTopbarMetaDisclosure();
    this.scheduleEditorLayout();
  }

  isStackedShellLayout() {
    return Boolean(globalThis.matchMedia?.(STACKED_LAYOUT_MEDIA_QUERY).matches);
  }

  getShellColumnGap() {
    if (!refs.shell) {
      return 0;
    }

    const computedStyle = globalThis.getComputedStyle(refs.shell);
    const gapValue = parseFloat(
      computedStyle.columnGap || computedStyle.gap || '0',
    );

    return Number.isFinite(gapValue) ? gapValue : 0;
  }

  getVisibleShellPanels() {
    return this.getPanelDefinitions()
      .filter((panel) => panel.isVisible())
      .map((panel) => ({
        ...panel,
        element: panel.getElement(),
      }))
      .filter((panel) => panel.element);
  }

  getShellResizeMetrics(visiblePanels = this.getVisibleShellPanels()) {
    const shellWidth = refs.shell?.clientWidth || 0;
    const columnGap = this.getShellColumnGap();
    const totalGapWidth = Math.max(visiblePanels.length - 1, 0) * columnGap;

    return {
      visiblePanels,
      visiblePanelCount: visiblePanels.length,
      shellWidth,
      columnGap,
      availableWidth: Math.max(shellWidth - totalGapWidth, 0),
      minimumRequiredWidth: visiblePanels.reduce(
        (sum, panel) => sum + panel.minWidth,
        0,
      ),
    };
  }

  getVisiblePanelWeights(
    visiblePanels = this.getVisibleShellPanels(),
    sourceWeights = state.panelSizeWeights,
  ) {
    const normalizedWeights =
      this.preferences.normalizePanelSizeWeights(sourceWeights);

    return visiblePanels.map((panel) => {
      const nextWeight = normalizedWeights[panel.key];
      return Number.isFinite(nextWeight) && nextWeight > 0
        ? nextWeight
        : this.preferences.getDefaultPanelSizeWeight();
    });
  }

  buildShellColumnsValue(visiblePanels, visiblePanelWeights) {
    if (visiblePanels.length <= 1) {
      return 'minmax(0, 1fr)';
    }

    return visiblePanels
      .map(
        (panel, index) =>
          `minmax(${panel.minWidth}px, ${visiblePanelWeights[index]}fr)`,
      )
      .join(' ');
  }

  canResizeShellPanels(visiblePanels = this.getVisibleShellPanels()) {
    const { visiblePanelCount, availableWidth, minimumRequiredWidth } =
      this.getShellResizeMetrics(visiblePanels);

    return (
      Boolean(refs.shell) &&
      visiblePanelCount > 1 &&
      !this.isStackedShellLayout() &&
      availableWidth >= minimumRequiredWidth
    );
  }

  applyPanelSizePreference() {
    if (!refs.shell) {
      return;
    }

    const visiblePanels = this.getVisibleShellPanels();
    const visiblePanelWeights = this.getVisiblePanelWeights(visiblePanels);

    state.panelSizeWeights = this.preferences.normalizePanelSizeWeights({
      ...state.panelSizeWeights,
      ...Object.fromEntries(
        visiblePanels.map((panel, index) => [
          panel.key,
          visiblePanelWeights[index],
        ]),
      ),
    });

    refs.shell.style.setProperty(
      '--shell-columns',
      this.buildShellColumnsValue(visiblePanels, visiblePanelWeights),
    );
  }

  getResizeHandleKey(leftPanelKey, rightPanelKey) {
    return `${leftPanelKey}:${rightPanelKey}`;
  }

  getShellResizeHandleMap() {
    return new Map(
      Array.from(
        refs.shellResizeHandles?.querySelectorAll('.editor-resize-handle') ||
          [],
      ).map((handle) => [handle.dataset.resizeHandleKey || '', handle]),
    );
  }

  createPanelResizeHandle(leftPanel, rightPanel) {
    const handle = document.createElement('div');
    handle.className = 'editor-resize-handle';
    handle.dataset.leftPanelKey = leftPanel.key;
    handle.dataset.rightPanelKey = rightPanel.key;
    handle.dataset.resizeHandleKey = this.getResizeHandleKey(
      leftPanel.key,
      rightPanel.key,
    );
    handle.setAttribute('role', 'separator');
    handle.setAttribute('aria-orientation', 'vertical');
    handle.setAttribute(
      'aria-label',
      `Resize ${leftPanel.label} and ${rightPanel.label}`,
    );
    handle.setAttribute(
      'aria-controls',
      `${leftPanel.element.id} ${rightPanel.element.id}`,
    );
    handle.addEventListener('pointerdown', this.handlePanelResizePointerDown);
    handle.addEventListener('pointermove', this.handlePanelResizePointerMove);
    handle.addEventListener('pointerup', this.handlePanelResizePointerUp);
    handle.addEventListener(
      'pointercancel',
      this.handlePanelResizePointerCancel,
    );
    handle.addEventListener(
      'lostpointercapture',
      this.handlePanelResizeLostPointerCapture,
    );
    handle.addEventListener('keydown', this.handlePanelResizeKeydown);
    handle.addEventListener('dblclick', this.handlePanelResizeDoubleClick);
    return handle;
  }

  getPanelPairFromHandle(handle, visiblePanels = this.getVisibleShellPanels()) {
    if (!(handle instanceof Element)) {
      return null;
    }

    const leftPanelKey = handle.dataset.leftPanelKey || '';
    const rightPanelKey = handle.dataset.rightPanelKey || '';
    const leftPanel = visiblePanels.find((panel) => panel.key === leftPanelKey);
    const rightPanel = visiblePanels.find(
      (panel) => panel.key === rightPanelKey,
    );

    if (!leftPanel || !rightPanel) {
      return null;
    }

    return { leftPanel, rightPanel };
  }

  getPanelPairMetrics(leftPanel, rightPanel) {
    return {
      columnGap: this.getShellColumnGap(),
      currentLeftWidth: leftPanel.element.offsetWidth,
      maxLeftWidth: Math.max(
        leftPanel.element.offsetWidth +
          rightPanel.element.offsetWidth -
          rightPanel.minWidth,
        leftPanel.minWidth,
      ),
      minLeftWidth: leftPanel.minWidth,
      pairWidth: leftPanel.element.offsetWidth + rightPanel.element.offsetWidth,
    };
  }

  getPanelResizeIntent(rawLeftPanelWidth, minLeftWidth, maxLeftWidth) {
    if (rawLeftPanelWidth <= minLeftWidth - PANEL_HIDE_POINTER_THRESHOLD_PX) {
      return 'hide-left';
    }

    if (rawLeftPanelWidth >= maxLeftWidth + PANEL_HIDE_POINTER_THRESHOLD_PX) {
      return 'hide-right';
    }

    return 'resize';
  }

  setPanelResizeHandleIntent(handle, intent, panelPair = null) {
    if (!(handle instanceof Element)) {
      return;
    }

    if (intent === 'hide-left' || intent === 'hide-right') {
      handle.dataset.resizeIntent = intent;
      const targetLabel =
        intent === 'hide-left'
          ? panelPair?.leftPanel.label
          : panelPair?.rightPanel.label;

      if (targetLabel) {
        handle.setAttribute('aria-valuetext', `Release to hide ${targetLabel}`);
      }

      return;
    }

    delete handle.dataset.resizeIntent;
    handle.removeAttribute('aria-valuetext');
  }

  getBalancedLeftPanelWidth(leftPanel, rightPanel) {
    const { minLeftWidth, maxLeftWidth, pairWidth } = this.getPanelPairMetrics(
      leftPanel,
      rightPanel,
    );

    if (pairWidth <= 0) {
      return leftPanel.element.offsetWidth;
    }

    return Math.min(Math.max(pairWidth / 2, minLeftWidth), maxLeftWidth);
  }

  updatePanelResizeHandlePosition(handle, leftPanel, rightPanel) {
    const handleWidth = handle.offsetWidth || RESIZE_HANDLE_WIDTH_FALLBACK_PX;
    const handleLeft =
      leftPanel.element.offsetLeft +
      leftPanel.element.offsetWidth +
      this.getShellColumnGap() / 2 -
      handleWidth / 2;
    const { currentLeftWidth, minLeftWidth, maxLeftWidth, pairWidth } =
      this.getPanelPairMetrics(leftPanel, rightPanel);

    handle.style.left = `${Math.max(handleLeft, 0)}px`;
    handle.setAttribute(
      'aria-valuemin',
      String(pairWidth > 0 ? Math.round((minLeftWidth / pairWidth) * 100) : 0),
    );
    handle.setAttribute(
      'aria-valuemax',
      String(
        pairWidth > 0 ? Math.round((maxLeftWidth / pairWidth) * 100) : 100,
      ),
    );
    handle.setAttribute(
      'aria-valuenow',
      String(
        pairWidth > 0 ? Math.round((currentLeftWidth / pairWidth) * 100) : 50,
      ),
    );
  }

  updatePanelResizeHandles() {
    if (!refs.shellResizeHandles) {
      return;
    }

    const visiblePanels = this.getVisibleShellPanels();
    const adjacentPairs = visiblePanels
      .slice(0, -1)
      .map((leftPanel, index) => ({
        key: this.getResizeHandleKey(
          leftPanel.key,
          visiblePanels[index + 1].key,
        ),
        leftPanel,
        rightPanel: visiblePanels[index + 1],
      }));
    const resizable = this.canResizeShellPanels(visiblePanels);

    if (
      this.activePanelResize &&
      (!resizable ||
        !adjacentPairs.some(
          (pair) => pair.key === this.activePanelResize.handleKey,
        ))
    ) {
      this.stopPanelResize();
    }

    refs.shell?.classList.toggle('editor-shell--resizable', resizable);
    refs.shell?.classList.toggle(
      'editor-shell--resizing',
      Boolean(this.activePanelResize),
    );

    if (!resizable || !adjacentPairs.length) {
      refs.shellResizeHandles.replaceChildren();
      return;
    }

    const handleMap = this.getShellResizeHandleMap();
    const nextHandleKeys = new Set();

    adjacentPairs.forEach(({ key, leftPanel, rightPanel }) => {
      nextHandleKeys.add(key);
      let handle = handleMap.get(key);

      if (!handle) {
        handle = this.createPanelResizeHandle(leftPanel, rightPanel);
        refs.shellResizeHandles.append(handle);
      }

      handle.dataset.leftPanelKey = leftPanel.key;
      handle.dataset.rightPanelKey = rightPanel.key;
      handle.dataset.resizeHandleKey = key;
      handle.setAttribute(
        'aria-label',
        `Resize ${leftPanel.label} and ${rightPanel.label}`,
      );
      handle.setAttribute(
        'aria-controls',
        `${leftPanel.element.id} ${rightPanel.element.id}`,
      );
      handle.hidden = false;
      handle.tabIndex = 0;
      this.updatePanelResizeHandlePosition(handle, leftPanel, rightPanel);
    });

    handleMap.forEach((handle, key) => {
      if (!nextHandleKeys.has(key)) {
        handle.remove();
      }
    });
  }

  captureVisiblePanelWidths(visiblePanels = this.getVisibleShellPanels()) {
    return visiblePanels.reduce((panelWidths, panel) => {
      panelWidths[panel.key] =
        panel.element.offsetWidth ||
        this.preferences.getDefaultPanelSizeWeight();
      return panelWidths;
    }, {});
  }

  setPanelSizeWeights(nextPanelSizeWeights, { persist = true } = {}) {
    state.panelSizeWeights = this.preferences.normalizePanelSizeWeights({
      ...state.panelSizeWeights,
      ...nextPanelSizeWeights,
    });

    if (persist) {
      this.preferences.savePanelSizePreference(state.panelSizeWeights);
    }

    this.scheduleEditorLayout();
  }

  setPanelPairWidths(
    leftPanel,
    rightPanel,
    leftPanelWidth,
    rightPanelWidth,
    options,
  ) {
    const nextPanelSizeWeights = this.captureVisiblePanelWidths();
    nextPanelSizeWeights[leftPanel.key] = leftPanelWidth;
    nextPanelSizeWeights[rightPanel.key] = rightPanelWidth;
    this.setPanelSizeWeights(nextPanelSizeWeights, options);
  }

  resetPanelPairWidths(leftPanel, rightPanel, options) {
    const { pairWidth } = this.getPanelPairMetrics(leftPanel, rightPanel);

    if (pairWidth <= 0) {
      return;
    }

    const nextLeftPanelWidth = this.getBalancedLeftPanelWidth(
      leftPanel,
      rightPanel,
    );

    this.setPanelPairWidths(
      leftPanel,
      rightPanel,
      nextLeftPanelWidth,
      pairWidth - nextLeftPanelWidth,
      options,
    );
  }

  getPanelResizeState(clientX, leftPanel, rightPanel) {
    if (!refs.shell) {
      return null;
    }

    const {
      columnGap,
      currentLeftWidth,
      maxLeftWidth,
      minLeftWidth,
      pairWidth,
    } = this.getPanelPairMetrics(leftPanel, rightPanel);

    if (pairWidth <= 0 || maxLeftWidth <= minLeftWidth) {
      return {
        nextLeftPanelWidth: currentLeftWidth,
        pairWidth,
        resizeIntent: 'resize',
      };
    }

    const shellRect = refs.shell.getBoundingClientRect();
    const rawLeftPanelWidth =
      clientX - shellRect.left - leftPanel.element.offsetLeft - columnGap / 2;

    return {
      nextLeftPanelWidth: Math.min(
        Math.max(rawLeftPanelWidth, minLeftWidth),
        maxLeftWidth,
      ),
      pairWidth,
      resizeIntent: this.getPanelResizeIntent(
        rawLeftPanelWidth,
        minLeftWidth,
        maxLeftWidth,
      ),
    };
  }

  updatePanelPairFromPointer(clientX, handle, options) {
    const panelPair = this.getPanelPairFromHandle(handle);
    if (!panelPair) {
      return null;
    }

    const resizeState = this.getPanelResizeState(
      clientX,
      panelPair.leftPanel,
      panelPair.rightPanel,
    );

    if (!resizeState) {
      return null;
    }

    this.setPanelResizeHandleIntent(
      handle,
      resizeState.resizeIntent,
      panelPair,
    );

    this.setPanelPairWidths(
      panelPair.leftPanel,
      panelPair.rightPanel,
      resizeState.nextLeftPanelWidth,
      resizeState.pairWidth - resizeState.nextLeftPanelWidth,
      options,
    );

    return {
      panelPair,
      ...resizeState,
    };
  }

  commitPanelResizeHide(panelPair, resizeIntent) {
    const panelKeyToHide =
      resizeIntent === 'hide-left'
        ? panelPair.leftPanel.key
        : resizeIntent === 'hide-right'
          ? panelPair.rightPanel.key
          : '';

    if (!panelKeyToHide) {
      this.stopPanelResize();
      return;
    }

    const initialPanelSizeWeights =
      this.activePanelResize?.initialPanelSizeWeights ?? null;

    if (initialPanelSizeWeights) {
      state.panelSizeWeights = this.preferences.normalizePanelSizeWeights(
        initialPanelSizeWeights,
      );
    }

    this.stopPanelResize({ persist: false });
    this.setPanelVisible(panelKeyToHide, false);
  }

  stopPanelResize({ persist = true } = {}) {
    if (!this.activePanelResize) {
      return;
    }

    const { handleElement, pointerId } = this.activePanelResize;
    this.setPanelResizeHandleIntent(handleElement, null);
    this.activePanelResize = null;

    if (handleElement?.hasPointerCapture?.(pointerId)) {
      try {
        handleElement.releasePointerCapture(pointerId);
      } catch (_error) {
        // Ignore release failures.
      }
    }

    document.documentElement.classList.remove('ol-editor-panel-resizing');
    refs.shell?.classList.remove('editor-shell--resizing');

    if (persist) {
      this.preferences.savePanelSizePreference(state.panelSizeWeights);
    }

    this.scheduleEditorLayout();
  }

  handlePanelResizePointerDown(event) {
    const handle =
      event.currentTarget instanceof Element ? event.currentTarget : null;
    if (!handle || event.button !== 0 || !this.canResizeShellPanels()) {
      return;
    }

    const panelPair = this.getPanelPairFromHandle(handle);
    if (!panelPair) {
      return;
    }

    event.preventDefault();
    hideChordDiagramPopup();
    this.activePanelResize = {
      handleElement: handle,
      handleKey:
        handle.dataset.resizeHandleKey ||
        this.getResizeHandleKey(
          panelPair.leftPanel.key,
          panelPair.rightPanel.key,
        ),
      pointerId: event.pointerId,
      initialPanelSizeWeights: { ...state.panelSizeWeights },
    };
    handle.setPointerCapture(event.pointerId);
    document.documentElement.classList.add('ol-editor-panel-resizing');
    refs.shell?.classList.add('editor-shell--resizing');
    this.updatePanelPairFromPointer(event.clientX, handle, { persist: false });
  }

  handlePanelResizePointerMove(event) {
    if (
      !this.activePanelResize ||
      event.pointerId !== this.activePanelResize.pointerId
    ) {
      return;
    }

    event.preventDefault();
    this.updatePanelPairFromPointer(
      event.clientX,
      this.activePanelResize.handleElement,
      { persist: false },
    );
  }

  handlePanelResizePointerUp(event) {
    if (
      !this.activePanelResize ||
      event.pointerId !== this.activePanelResize.pointerId
    ) {
      return;
    }

    event.preventDefault();
    const resizeState = this.updatePanelPairFromPointer(
      event.clientX,
      this.activePanelResize.handleElement,
      { persist: false },
    );

    if (!resizeState) {
      this.stopPanelResize();
      return;
    }

    if (
      resizeState.resizeIntent === 'hide-left' ||
      resizeState.resizeIntent === 'hide-right'
    ) {
      this.commitPanelResizeHide(
        resizeState.panelPair,
        resizeState.resizeIntent,
      );
      return;
    }

    this.stopPanelResize();
  }

  handlePanelResizePointerCancel(event) {
    if (
      !this.activePanelResize ||
      event.pointerId !== this.activePanelResize.pointerId
    ) {
      return;
    }

    this.stopPanelResize();
  }

  handlePanelResizeLostPointerCapture(event) {
    if (
      !this.activePanelResize ||
      event.pointerId !== this.activePanelResize.pointerId
    ) {
      return;
    }

    this.stopPanelResize();
  }

  handlePanelResizeKeydown(event) {
    const handle =
      event.currentTarget instanceof Element ? event.currentTarget : null;
    const panelPair = this.getPanelPairFromHandle(handle);

    if (!panelPair || !this.canResizeShellPanels()) {
      return;
    }

    const { currentLeftWidth, maxLeftWidth, minLeftWidth, pairWidth } =
      this.getPanelPairMetrics(panelPair.leftPanel, panelPair.rightPanel);
    const stepWidth = Math.max(
      12,
      (pairWidth * RESIZE_KEYBOARD_STEP_PERCENT) / 100,
    );
    let nextLeftWidth = null;

    if (event.key === 'ArrowLeft') {
      nextLeftWidth = currentLeftWidth - stepWidth;
    } else if (event.key === 'ArrowRight') {
      nextLeftWidth = currentLeftWidth + stepWidth;
    } else if (event.key === 'Home') {
      nextLeftWidth = minLeftWidth;
    } else if (event.key === 'End') {
      nextLeftWidth = maxLeftWidth;
    }

    if (nextLeftWidth === null) {
      return;
    }

    event.preventDefault();
    hideChordDiagramPopup();
    const clampedLeftWidth = Math.min(
      Math.max(nextLeftWidth, minLeftWidth),
      maxLeftWidth,
    );
    this.setPanelPairWidths(
      panelPair.leftPanel,
      panelPair.rightPanel,
      clampedLeftWidth,
      pairWidth - clampedLeftWidth,
      { persist: true },
    );
  }

  handlePanelResizeDoubleClick(event) {
    const handle =
      event.currentTarget instanceof Element ? event.currentTarget : null;
    const panelPair = this.getPanelPairFromHandle(handle);

    if (!panelPair || !this.canResizeShellPanels()) {
      return;
    }

    event.preventDefault();
    hideChordDiagramPopup();

    if (this.activePanelResize) {
      this.stopPanelResize({ persist: false });
    }

    this.resetPanelPairWidths(panelPair.leftPanel, panelPair.rightPanel, {
      persist: true,
    });
  }

  setPanelVisible(panelKey, nextVisible) {
    if (panelKey === 'editor') {
      this.setEditorVisible(nextVisible);
      return;
    }

    if (panelKey === 'preview') {
      this.setPreviewVisible(nextVisible);
      return;
    }

    if (panelKey === 'openLyric') {
      this.setOpenLyricVisible(nextVisible);
    }
  }

  updatePanelToggleButton(button, isVisible, visibleLabel, hiddenLabel) {
    if (!(button instanceof HTMLButtonElement)) {
      return;
    }

    const nextLabel = isVisible ? visibleLabel : hiddenLabel;
    const labelElement = button.querySelector('[data-panel-toggle-label]');

    if (labelElement) {
      labelElement.textContent = nextLabel;
    }

    button.setAttribute('aria-label', nextLabel);
    button.setAttribute('aria-pressed', String(isVisible));
    button.title = nextLabel;
  }

  syncTopbarMetaDisclosure() {
    const topbarMeta = refs.topbarMeta;

    if (!(topbarMeta instanceof HTMLDetailsElement)) {
      return;
    }

    const isMobile = this.isStackedShellLayout();

    if (this.topbarMetaMobileState === isMobile) {
      if (!isMobile) {
        topbarMeta.open = true;
      }

      return;
    }

    this.topbarMetaMobileState = isMobile;
    topbarMeta.open = !isMobile;
  }

  applyPanelVisibilityPreference(value) {
    const panelVisibility =
      this.preferences.normalizePanelVisibilityPreference(value);

    state.editorVisible = panelVisibility.editorVisible;
    state.previewVisible = panelVisibility.previewVisible;
    state.openLyricVisible = panelVisibility.openLyricVisible;
    this.getEffectivePanelVisibility();
  }

  updateShellPanels() {
    const panelVisibility = this.getEffectivePanelVisibility();
    const effectiveOpenLyricVisible = panelVisibility.openLyricVisible;

    if (refs.editorPanel) {
      refs.editorPanel.style.display = panelVisibility.editorVisible
        ? 'flex'
        : 'none';
    }

    if (refs.openLyricPanel) {
      refs.openLyricPanel.style.display = effectiveOpenLyricVisible
        ? 'flex'
        : 'none';
    }

    if (refs.previewPanel) {
      refs.previewPanel.style.display = panelVisibility.previewVisible
        ? 'block'
        : 'none';
    }

    this.syncTopbarMetaDisclosure();

    this.applyPanelSizePreference();
    this.updatePanelResizeHandles();

    this.updatePanelToggleButton(
      refs.toggleEditorBtn,
      panelVisibility.editorVisible,
      'Hide editor panel',
      'Show editor panel',
    );
    this.updatePanelToggleButton(
      refs.togglePreviewBtn,
      panelVisibility.previewVisible,
      'Hide markdown preview panel',
      'Show markdown preview panel',
    );
    if (refs.toggleOpenLyricBtn) {
      refs.toggleOpenLyricBtn.hidden = false;
      refs.toggleOpenLyricBtn.disabled = false;
    }

    if (this.isOpenLyricPanelAvailable()) {
      this.updatePanelToggleButton(
        refs.toggleOpenLyricBtn,
        effectiveOpenLyricVisible,
        'Hide Open Lyric preview panel',
        'Show Open Lyric preview panel',
      );
    } else {
      this.updatePanelToggleButton(
        refs.toggleOpenLyricBtn,
        false,
        'Enable Open Lyric plugin',
        'Enable Open Lyric plugin',
      );
    }

    if (this.hasSupplementalShellPanels()) {
      this.preferences.savePanelVisibilityPreference({
        editorVisible: state.editorVisible,
        previewVisible: state.previewVisible,
        openLyricVisible: state.openLyricVisible,
      });
    }

    this.onPanelVisibilityChange?.({
      editorVisible: panelVisibility.editorVisible,
      previewVisible: panelVisibility.previewVisible,
      openLyricVisible: effectiveOpenLyricVisible,
    });
    this.scheduleEditorLayout();
  }

  setEditorVisible(nextVisible) {
    state.editorVisible = Boolean(nextVisible);

    if (
      !state.editorVisible &&
      !state.previewVisible &&
      !state.openLyricVisible
    ) {
      state.previewVisible = true;
    }

    this.updateShellPanels();
  }

  setPreviewVisible(nextVisible) {
    state.previewVisible = Boolean(nextVisible);

    if (
      !state.previewVisible &&
      !state.editorVisible &&
      !state.openLyricVisible
    ) {
      state.editorVisible = true;
    }

    this.updateShellPanels();
  }

  setOpenLyricVisible(nextVisible) {
    state.openLyricVisible = Boolean(nextVisible);

    if (
      !state.openLyricVisible &&
      !state.editorVisible &&
      !state.previewVisible
    ) {
      state.editorVisible = true;
      state.previewVisible = true;
    }

    this.updateShellPanels();
  }

  togglePreview() {
    this.setPreviewVisible(!state.previewVisible);
  }

  toggleOpenLyric() {
    this.setOpenLyricVisible(!state.openLyricVisible);
  }

  toggleEditor() {
    this.setEditorVisible(!state.editorVisible);
  }
}

export { ShellLayoutController };
