import { olEditorOpenLyricPluginData } from './OpenLyric/index.ts';
import { olEditorPluginData } from './km_KH/km_KH_ol_editor.ts';
import { olEditorTranscriptPluginData } from './transcript/index.ts';
import {
  registerPlugin,
  unregisterPlugin,
} from '../scripts/editor-plugin-registry.ts';
import { loadOpenLyricPluginEnabledPreference } from '../scripts/open-lyric-plugin-preference.ts';

type BuiltInPluginRegistration = ReturnType<typeof registerPlugin>;

/**
 * Built-in registration state. Module-scoped (not `globalThis`): this module
 * is a singleton within the page's module graph, which is all the de-duping
 * these guards ever needed.
 */
let khmerRegistration: BuiltInPluginRegistration | undefined;
let openLyricRegistration: BuiltInPluginRegistration | undefined;
let transcriptRegistration: BuiltInPluginRegistration | undefined;
let openLyricPluginEnabled: boolean | undefined;

function isBuiltInOpenLyricPluginEnabled() {
  if (typeof openLyricPluginEnabled !== 'boolean') {
    openLyricPluginEnabled = loadOpenLyricPluginEnabledPreference();
  }

  return openLyricPluginEnabled;
}

/** The live OpenLyric notation registration, or null while disabled. */
function getBuiltInOpenLyricPluginRegistration() {
  return openLyricRegistration && !openLyricRegistration.disposed
    ? openLyricRegistration
    : null;
}

function setBuiltInOpenLyricPluginEnabled(enabled) {
  const nextEnabled = Boolean(enabled);
  const currentRegistration = openLyricRegistration;

  openLyricPluginEnabled = nextEnabled;

  if (!nextEnabled) {
    if (currentRegistration && !currentRegistration.disposed) {
      unregisterPlugin(currentRegistration);
    }

    openLyricRegistration = undefined;
    return null;
  }

  if (currentRegistration && !currentRegistration.disposed) {
    return currentRegistration;
  }

  const registration = registerPlugin(olEditorOpenLyricPluginData);
  openLyricRegistration = registration;
  return registration;
}

function registerBuiltInEditorPlugins({
  includeOpenLyricPlugin = true,
  includeKhmerPlugin = true,
  includeTranscriptPlugin = true,
} = {}) {
  const khmerPluginRegistration = includeKhmerPlugin
    ? khmerRegistration || registerPlugin(olEditorPluginData)
    : null;
  const openLyricPluginRegistration = includeOpenLyricPlugin
    ? setBuiltInOpenLyricPluginEnabled(isBuiltInOpenLyricPluginEnabled())
    : setBuiltInOpenLyricPluginEnabled(false);
  const transcriptPluginRegistration = includeTranscriptPlugin
    ? transcriptRegistration || registerPlugin(olEditorTranscriptPluginData)
    : null;

  khmerRegistration = khmerPluginRegistration || khmerRegistration;
  transcriptRegistration =
    transcriptPluginRegistration || transcriptRegistration;

  return {
    khmerPluginRegistration,
    openLyricPluginRegistration,
    transcriptPluginRegistration,
  };
}

export {
  getBuiltInOpenLyricPluginRegistration,
  isBuiltInOpenLyricPluginEnabled,
  registerBuiltInEditorPlugins,
  setBuiltInOpenLyricPluginEnabled,
};
