import type {
  OpenLyricEventHandler,
  OpenLyricEventMap,
  OpenLyricEventName,
  Unsubscribe,
} from './types.ts';

type AnyHandler = (payload: unknown) => void;

/**
 * A tiny, dependency-free typed event bus. One instance is owned by each
 * component (composition, not inheritance) and backs the public `on()` API.
 *
 * - `on()` returns an unsubscribe function (the redesign's unified contract).
 * - `emit()` never lets one bad listener break the others.
 * - `clear()` drops every listener; components call it during `destroy()`.
 */
export class OpenLyricEventEmitter {
  private readonly handlers = new Map<OpenLyricEventName, Set<AnyHandler>>();

  on<E extends OpenLyricEventName>(
    event: E,
    handler: OpenLyricEventHandler<E>,
  ): Unsubscribe {
    if (typeof handler !== 'function') {
      return () => {};
    }

    let handlerSet = this.handlers.get(event);
    if (!handlerSet) {
      handlerSet = new Set();
      this.handlers.set(event, handlerSet);
    }

    const anyHandler = handler as AnyHandler;
    handlerSet.add(anyHandler);

    let subscribed = true;
    return () => {
      if (!subscribed) {
        return;
      }
      subscribed = false;
      handlerSet?.delete(anyHandler);
    };
  }

  off<E extends OpenLyricEventName>(
    event: E,
    handler: OpenLyricEventHandler<E>,
  ): void {
    this.handlers.get(event)?.delete(handler as AnyHandler);
  }

  emit<E extends OpenLyricEventName>(
    event: E,
    payload: OpenLyricEventMap[E],
  ): void {
    const handlerSet = this.handlers.get(event);
    if (!handlerSet || !handlerSet.size) {
      return;
    }

    // Snapshot so a handler that (un)subscribes mid-dispatch is well-behaved.
    for (const handler of Array.from(handlerSet)) {
      try {
        handler(payload);
      } catch (error) {
        console.error(`Open Lyric "${event}" listener failed.`, error);
      }
    }
  }

  clear(): void {
    this.handlers.clear();
  }
}
