import { OpenLyricPreviewComponent } from './internal/OpenLyricPreviewComponent.ts';
import { rasterizeNodeToDataUrl } from './internal/rasterize.ts';
import { OPEN_LYRIC_THEME_PRESETS } from './internal/theme.ts';
import type {
  OpenLyricPreviewOptions,
  OpenLyricSurface,
} from './internal/types.ts';
import { installOpenLyricShellMarkup } from '../plugins/OpenLyric/html/install-shell-markup.ts';
import {
  createOpenLyricPresentationData,
  createOpenLyricStructureControlState,
  renderOpenLyricPlainText,
  renderOpenLyricPreview,
} from '../plugins/OpenLyric/preview/index.ts';
import {
  ensurePreviewStylesInjected,
  getInjectablePreviewStyleCss,
} from './internal/preview-styles.ts';
import { OpenLyricStandaloneChrome } from './internal/OpenLyricStandaloneChrome.ts';
import { refreshElementRefs } from '../scripts/shared.ts';

/** The fixed structure id the preview uses for its single Config structure. */
const STRUCTURE_KEY_ID = 'config-structure';

export interface OpenLyricSectionInfo {
  partName: string;
  repeatText: string;
  heading: string;
}

export interface OpenLyricInfo {
  title: string;
  secondaryText: string;
  key: string;
  metaLine: string;
  structureLine: string;
  sections: OpenLyricSectionInfo[];
}

export interface OpenLyricElementMapOptions {
  /** Map each section to its plain-text body (the default). */
  isText?: boolean;
  /** Map each section to its rendered HTML (`<section …>…</section>`). */
  isHtml?: boolean;
  /**
   * Map each section to a `data:image/png;base64,…` URI of the rasterized
   * section. Requires a mounted preview.
   */
  isPngImageData?: boolean;
  /**
   * Keep the inline key notes — the `[chord]` markers and the leading `|`
   * bars. Off by default, so the map holds lyrics only.
   */
  isWithKeyNote?: boolean;
}

export interface OpenLyricValueOptions {
  /** Produce the whole-song plain text — the default (= "Copy as Text"). */
  isText?: boolean;
  /** Produce the whole-song rendered HTML. */
  isHtml?: boolean;
  /**
   * Produce a `data:image/png;base64,…` URI of the whole song — the same
   * rendered image the preview panel's **Download as Image** action captures
   * (background, fonts, and full width), as PNG. Requires a mounted preview.
   */
  isPngImageData?: boolean;
  /**
   * Override the inline key notes — the `[chord]` markers and leading `|`
   * bars. `true` forces them on, `false` forces them off. Omit to follow the
   * preview's current Hide Keys / Hide Bars state (what Copy as Text /
   * Download as Image reproduce).
   */
  isWithKeyNote?: boolean;
}

export interface OpenLyricOptions extends OpenLyricPreviewOptions {
  /** Simplify chord symbols (drop extensions). */
  isSimplified?: boolean;
  /** Hide leading `|` bar markers in lyric lines. */
  isBarsHidden?: boolean;
  /** Hide inline `[chord]` key markers. */
  isKeyNotesHidden?: boolean;
  /** Transpose the song to this key (empty = original Config key). */
  keyNote?: string;
  /**
   * Hide the standalone preview's floating controls — the settings gear (font
   * size/family, plugin toggle, key transpose, Simply / Hide Bars / Hide Keys)
   * and the actions `⋮` menu (Copy as Text, Download as Image, Print, Download
   * as PowerPoint). A standalone (non-adopt) embed always renders the preview
   * panel chrome — floating tools, export-progress bar, and guitar chord hover
   * popover; this only hides the interactive controls, which show by default.
   * No effect when the component adopts a host-owned container
   * (`adoptContainer`), where the host page owns the chrome. Toggle later via
   * the `isControlHidden` accessor.
   */
  isControlHidden?: boolean;
  /**
   * Skip injecting the default Open Lyric preview styles into the document.
   * Useful if the host page already includes them or wants to manage styles
   * manually. Only affects the standalone preview; has no effect on adopted
   * containers.
   */
  isSkipStyleInjection?: boolean;
}

/**
 * `OpenLyric` — the standalone lyric preview (`glpp`).
 *
 * Renders the Open Lyric song view from markdown with no editor and no
 * dashboard required. Attaching an editor (see `editor` / `isWeakRef` on the
 * base) upgrades double-clicks into caret jumps; without one, double-clicks
 * still emit `part-dblclick` for the host to handle.
 *
 * Backed by the pure render/analysis functions in
 * `editor/plugins/OpenLyric/preview/index.ts`.
 */
export class OpenLyric extends OpenLyricPreviewComponent {
  readonly surface: OpenLyricSurface = 'lyric';

  /**
   * Install the OpenLyric page-shell markup — the lyric panel
   * (`#openLyricPanel`), its topbar toggle, the preview-settings fields,
   * and the chord-bars action inside the editor panel — the lyric preview
   * surface owns its shell markup. The full page entry
   * (`main-open-lyric.ts`) calls this before composing and booting the
   * app; the app's captured element refs refresh afterwards.
   * Idempotent, and a no-op on pages without the mounts. Call
   * `Editor.installShellMarkup()` first — the chord-bars action mounts
   * inside the editor panel.
   */
  static installShellMarkup(): void {
    installOpenLyricShellMarkup();
    refreshElementRefs();
  }

  /**
   * The Open Lyric preview stylesheet (the song view + `.ol-preview-*` fence
   * cards) as a raw CSS string — exactly what a standalone embed injects into
   * `<head>` on construction. Pass `isSkipStyleInjection: true` to suppress the
   * automatic injection, then inject this yourself (e.g. into a shadow root or
   * a scoped `<style>`).
   */
  static getInjectableStyle(): string {
    return getInjectablePreviewStyleCss();
  }

  private simplifyChordsValue = false;
  private barsHiddenValue = false;
  private keyNotesHiddenValue = false;
  private keyNoteValue = '';
  private controlHiddenValue = false;
  private standaloneChrome: OpenLyricStandaloneChrome | null = null;

  constructor(options: OpenLyricOptions = {}) {
    super(options);
    // Inject the preview stylesheet unless the host opts to manage styles
    // itself (`isSkipStyleInjection` + `OpenLyric.getInjectableStyle()`).
    if (!options.isSkipStyleInjection) {
      ensurePreviewStylesInjected();
    }
    this.simplifyChordsValue = Boolean(options.isSimplified);
    this.barsHiddenValue = Boolean(options.isBarsHidden);
    this.keyNotesHiddenValue = Boolean(options.isKeyNotesHidden);
    this.keyNoteValue = options.keyNote ? String(options.keyNote) : '';
    this.controlHiddenValue = Boolean(options.isControlHidden);
  }

  /* ------------------------------ lifecycle ------------------------------ */

  protected override handleMount(container: HTMLElement): void {
    super.handleMount(container);
    // A standalone (non-adopt) embed renders the full preview panel chrome —
    // settings popup, actions menu, export progress, and the chord popover —
    // around the render root; hide just the floating controls with
    // `isControlHidden`. Adopt-mode embeds keep deferring that chrome to their
    // host (the app page owns it there).
    if (this.adoptContainer) {
      return;
    }
    const root = this.getRenderRoot();
    if (!root) {
      return;
    }
    this.standaloneChrome = new OpenLyricStandaloneChrome(this);
    this.standaloneChrome.attach(root, container);
  }

  protected override handleUnmount(): void {
    this.standaloneChrome?.destroy();
    this.standaloneChrome = null;
    super.handleUnmount();
  }

  /* ------------------------------ options -------------------------------- */

  get isSimplified(): boolean {
    return this.simplifyChordsValue;
  }

  set isSimplified(next: boolean) {
    const value = Boolean(next);
    const changed = value !== this.simplifyChordsValue;
    this.simplifyChordsValue = value;
    this.renderNow();
    if (changed) {
      this.emitDisplayChange();
    }
  }

  get isBarsHidden(): boolean {
    return this.barsHiddenValue;
  }

  set isBarsHidden(next: boolean) {
    const value = Boolean(next);
    const changed = value !== this.barsHiddenValue;
    this.barsHiddenValue = value;
    this.renderNow();
    if (changed) {
      this.emitDisplayChange();
    }
  }

  get isKeyNotesHidden(): boolean {
    return this.keyNotesHiddenValue;
  }

  set isKeyNotesHidden(next: boolean) {
    const value = Boolean(next);
    const changed = value !== this.keyNotesHiddenValue;
    this.keyNotesHiddenValue = value;
    this.renderNow();
    if (changed) {
      this.emitDisplayChange();
    }
  }

  /**
   * Whether the standalone chrome's floating controls (the settings gear and
   * the actions `⋮` menu) are hidden. Only affects a standalone (non-adopt)
   * embed; a no-op where the host owns the chrome.
   */
  get isControlHidden(): boolean {
    return this.controlHiddenValue;
  }

  set isControlHidden(next: boolean) {
    this.controlHiddenValue = Boolean(next);
    this.standaloneChrome?.setControlHidden(this.controlHiddenValue);
  }

  /**
   * Restore the preview settings to their defaults — the programmatic
   * equivalent of the standalone chrome's "Reset" button: clears chord
   * simplification, hidden bars/keys, and transposition, and returns the font
   * size/family to the preview defaults. On a standalone embed the settings
   * popup drives the reset (so its controls and persisted typography reset too);
   * where the host owns the chrome, this resets the component's own state and
   * clears any font overrides.
   */
  resetPreviewSetting(): void {
    if (this.standaloneChrome) {
      this.standaloneChrome.reset();
      return;
    }
    this.isSimplified = false;
    this.isBarsHidden = false;
    this.isKeyNotesHidden = false;
    this.keyNote = '';
    this.fontSize = '';
    this.fontFamily = '';
  }

  /** Selectable musical keys for transposition (empty if there is no Config). */
  getKeys(): string[] {
    return this.getStructureControlState()?.keyOptions ?? [];
  }

  get keyNote(): string {
    if (this.keyNoteValue) {
      return this.keyNoteValue;
    }
    return this.getStructureControlState()?.selectedKeyText ?? '';
  }

  set keyNote(next: string) {
    const value = next ? String(next) : '';
    const changed = value !== this.keyNoteValue;
    this.keyNoteValue = value;
    this.renderNow();
    if (changed) {
      this.emitDisplayChange();
    }
  }

  /**
   * Announce a song-display change (chord simplification, hidden bars/keys, or
   * transposition) so host UI and the standalone chrome's settings controls can
   * mirror a programmatic set — the display counterpart to `typography-change`.
   */
  private emitDisplayChange(): void {
    this.emitter.emit('display-change', {
      isSimplified: this.simplifyChordsValue,
      isBarsHidden: this.barsHiddenValue,
      isKeyNotesHidden: this.keyNotesHiddenValue,
      keyNote: this.keyNoteValue,
    });
  }

  /* ------------------------------ getters -------------------------------- */

  /**
   * The song's structure — the ordered list of section (part) names as they
   * appear in the Config `Structure`, e.g. `['Intro', 'Verse 1', 'Chorus',
   * 'Verse 2', 'Outro']`. A part repeated in the flow appears once per step.
   * Empty when there is no Config/Structure.
   */
  getStructure(): string[] {
    const data = createOpenLyricPresentationData(
      this.value,
      this.getContentRenderOptions(),
    );
    if (!data || !Array.isArray(data.sections)) {
      return [];
    }
    return data.sections
      .map((section: any) => String(section?.partName ?? ''))
      .filter(Boolean);
  }

  /**
   * A map from section (part) name to that section's rendered content — one
   * entry per unique part in the structure. The value's form is chosen by the
   * option flag:
   *
   * - `{ isText: true }` (default) — the section body as plain text.
   * - `{ isHtml: true }` — the section's rendered HTML (`<section …>…`).
   * - `{ isPngImageData: true }` — a `data:image/png;base64,…` URI of the
   *   rasterized section (requires a mounted preview).
   *
   * By default the map holds lyrics only — the inline key notes (the `[chord]`
   * markers and leading `|` bars) are stripped. Pass `{ isWithKeyNote: true }`
   * to keep them.
   *
   * Always async: PNG rasterization is deferred, and the text/HTML variants
   * resolve on the same contract so callers have one uniform call shape.
   */
  async getElementMap(
    options: OpenLyricElementMapOptions = {},
  ): Promise<Record<string, string>> {
    const renderOptions = this.getContentRenderOptions(
      options.isWithKeyNote === true,
    );
    if (options.isPngImageData) {
      return this.buildImageElementMap(renderOptions);
    }
    if (options.isHtml) {
      return this.buildHtmlElementMap(renderOptions);
    }
    return this.buildTextElementMap(renderOptions);
  }

  /**
   * The whole song rendered as a single value — the counterpart to
   * {@link getElementMap} (which returns one entry per section). The value's
   * form is chosen by the option flag:
   *
   * - `{ isText: true }` (default) — the full plain-text render, identical to
   *   the preview panel's **Copy as Text** action (title, meta, structure, and
   *   every section joined).
   * - `{ isHtml: true }` — the whole-song rendered HTML.
   * - `{ isPngImageData: true }` — a `data:image/png;base64,…` URI of the
   *   whole song, the same image the **Download as Image** action captures
   *   (surface background, loaded fonts, full width), as PNG. Requires a
   *   mounted preview.
   *
   * The inline key notes (the `[chord]` markers and leading `|` bars) follow
   * the preview's current Hide Keys / Hide Bars state by default — so these
   * mirror the app's Copy as Text / Download as Image output. Pass
   * `isWithKeyNote: true` to force them on or `false` to force them off.
   *
   * Async for the same reason as {@link getElementMap}: image rasterization is
   * deferred, so every variant resolves on one uniform call shape.
   */
  async getValue(options: OpenLyricValueOptions = {}): Promise<string> {
    const renderOptions = this.getContentRenderOptions(
      options.isWithKeyNote === undefined ? 'inherit' : options.isWithKeyNote,
    );
    if (options.isPngImageData) {
      return this.buildPngImageData(renderOptions);
    }
    if (options.isHtml) {
      return this.renderMarkup(this.value, renderOptions);
    }
    return renderOpenLyricPlainText(this.value, renderOptions);
  }

  /** Song metadata: title, sections, key, structure. */
  getInfo(): OpenLyricInfo | null {
    const data = createOpenLyricPresentationData(
      this.value,
      this.getRenderOptions(),
    );
    if (!data) {
      return null;
    }
    return {
      title: data.title,
      secondaryText: data.secondaryText,
      key: this.keyNote,
      metaLine: data.metaLine,
      structureLine: data.structureLine,
      sections: (Array.isArray(data.sections) ? data.sections : []).map(
        (section: any) => ({
          partName: section.partName ?? '',
          repeatText: section.repeatText ?? '',
          heading: section.heading ?? '',
        }),
      ),
    };
  }

  /* ------------------------- render contract ----------------------------- */

  protected rootClassName(): string {
    return 'ol-lyric-preview';
  }

  protected override resolveRendererTarget(target: string) {
    if (target === 'key-note') {
      // Every inline [chord] marker and meta chord the song view renders.
      return {
        selector: '.ol-preview-chord[data-chord-key]',
        getText: (element: Element) =>
          element.getAttribute('data-chord-key') ?? '',
      };
    }
    return super.resolveRendererTarget(target);
  }

  protected override decorateRenderedDom(root: HTMLElement): void {
    const preset = OPEN_LYRIC_THEME_PRESETS[this.theme];
    for (const chord of root.querySelectorAll<HTMLElement>(
      '.ol-preview-chord',
    )) {
      chord.style.color = `var(--ol-chord-color, ${preset.chordColor})`;
    }
    for (const title of root.querySelectorAll<HTMLElement>(
      '.ol-song-view__section-title',
    )) {
      title.style.color = `var(--ol-accent, ${preset.accent})`;
    }
  }

  protected renderMarkup(
    value: string,
    options: Record<string, unknown>,
  ): string {
    return renderOpenLyricPreview(value, options);
  }

  protected override getRenderOptions(): Record<string, unknown> {
    return {
      simplifyChords: this.simplifyChordsValue,
      hideLeadingBars: this.barsHiddenValue,
      hideBracketedKeys: this.keyNotesHiddenValue,
      selectedStructureKeys: this.keyNoteValue
        ? { [STRUCTURE_KEY_ID]: this.keyNoteValue }
        : {},
    };
  }

  /* ------------------------------ internals ------------------------------ */

  private getStructureControlState() {
    return createOpenLyricStructureControlState(this.value, {
      selectedStructureKeys: this.keyNoteValue
        ? { [STRUCTURE_KEY_ID]: this.keyNoteValue }
        : {},
    });
  }

  /**
   * The render options for the content getters. `keyNote` controls the inline
   * key notes — the `[chord]` markers and leading `|` bars:
   * - `'inherit'` — leave them to the component's current Hide Keys / Hide Bars
   *   state (what the preview shows, and what Copy as Text / Download as Image
   *   reproduce).
   * - `true` — force the key notes on.
   * - `false` — force them off, leaving the lyrics only.
   */
  private getContentRenderOptions(
    keyNote: boolean | 'inherit' = 'inherit',
  ): Record<string, unknown> {
    const base = {
      ...this.getRenderOptions(),
      ...(this.extraRenderOptions || {}),
    };
    if (keyNote === 'inherit') {
      return base;
    }
    return {
      ...base,
      hideBracketedKeys: !keyNote,
      hideLeadingBars: !keyNote,
    };
  }

  private buildTextElementMap(
    renderOptions: Record<string, unknown>,
  ): Record<string, string> {
    const map: Record<string, string> = {};
    const data = createOpenLyricPresentationData(this.value, renderOptions);
    if (!data || !Array.isArray(data.sections)) {
      return map;
    }
    for (const section of data.sections) {
      const partName = String((section as any)?.partName ?? '');
      if (partName) {
        map[partName] = extractSectionBodyText(section);
      }
    }
    return map;
  }

  private buildHtmlElementMap(
    renderOptions: Record<string, unknown>,
  ): Record<string, string> {
    const map: Record<string, string> = {};
    const html = this.renderMarkup(this.value, renderOptions);
    if (!html.trim()) {
      return map;
    }
    const doc = new DOMParser().parseFromString(html, 'text/html');
    for (const section of doc.querySelectorAll('.ol-song-view__section')) {
      const partName = section.getAttribute('data-ol-part-name') ?? '';
      if (partName) {
        map[partName] = section.outerHTML;
      }
    }
    return map;
  }

  private async buildImageElementMap(
    renderOptions: Record<string, unknown>,
  ): Promise<Record<string, string>> {
    const liveRoot = this.getRenderRoot();
    if (!liveRoot) {
      throw new Error(
        'getElementMap({ isPngImageData: true }) requires a mounted preview.',
      );
    }
    const surface = this.buildImageExportSurface(liveRoot, renderOptions);
    const stage = mountOffscreen(surface);
    try {
      await waitForDocumentFonts();
      const map: Record<string, string> = {};
      const sections = surface.querySelectorAll<HTMLElement>(
        '.ol-song-view__section',
      );
      for (const section of sections) {
        const partName = section.getAttribute('data-ol-part-name') ?? '';
        if (partName) {
          map[partName] = await rasterizeNodeToDataUrl(section);
        }
      }
      return map;
    } finally {
      stage.remove();
    }
  }

  /**
   * The whole song as a PNG data URI, matching the **Download as Image**
   * action: the surface carries its resolved background and typography, fonts
   * finish loading before the raster, and the output spans the full rendered
   * width/height.
   */
  private async buildPngImageData(
    renderOptions: Record<string, unknown>,
  ): Promise<string> {
    const liveRoot = this.getRenderRoot();
    if (!liveRoot) {
      throw new Error(
        'getValue({ isPngImageData: true }) requires a mounted preview.',
      );
    }
    const surface = this.buildImageExportSurface(liveRoot, renderOptions);
    const stage = mountOffscreen(surface);
    try {
      await waitForDocumentFonts();
      return await rasterizeNodeToDataUrl(surface, {
        backgroundColor: this.resolveSurfaceBackground(liveRoot),
        pixelRatio: Math.max(2, Math.min(3, globalThis.devicePixelRatio || 1)),
        width: Math.max(surface.scrollWidth, surface.offsetWidth),
        height: Math.max(surface.scrollHeight, surface.offsetHeight),
      });
    } finally {
      stage.remove();
    }
  }

  /**
   * An off-screen clone of the render root carrying `renderOptions`' markup —
   * the surface both image getters rasterize. It mirrors the live root's
   * resolved typography and background and lays out at the full preview width,
   * so the raster matches what **Download as Image** captures.
   */
  private buildImageExportSurface(
    liveRoot: HTMLElement,
    renderOptions: Record<string, unknown>,
  ): HTMLElement {
    const style = globalThis.getComputedStyle(liveRoot);
    const surface = document.createElement('article');
    surface.className = liveRoot.className;
    surface.setAttribute('data-ol-theme', this.theme);
    surface.innerHTML = this.renderMarkup(this.value, renderOptions);
    // Mounted off-screen alongside the live preview — drop ids so they do not
    // duplicate the live document's.
    surface.querySelectorAll('[id]').forEach((el) => el.removeAttribute('id'));
    this.decorateRenderedDom(surface);
    surface.style.boxSizing = 'border-box';
    surface.style.fontFamily = style.fontFamily;
    surface.style.fontSize = style.fontSize;
    surface.style.lineHeight = style.lineHeight;
    surface.style.color = style.color;
    surface.style.background = this.resolveSurfaceBackground(liveRoot);
    surface.style.padding = style.padding;
    surface.style.height = 'auto';
    surface.style.maxHeight = 'none';
    surface.style.overflow = 'visible';
    surface.style.margin = '0';
    surface.style.width = `${Math.max(
      liveRoot.clientWidth,
      liveRoot.scrollWidth,
      640,
    )}px`;
    return surface;
  }

  /**
   * The colour to fill behind the rasterized song — the live root's own
   * (non-transparent) background, else the theme's default surface — so the
   * exported image is never see-through.
   */
  private resolveSurfaceBackground(liveRoot: HTMLElement): string {
    const rootColor = globalThis.getComputedStyle(liveRoot).backgroundColor;
    if (!isTransparentColor(rootColor)) {
      return rootColor;
    }
    return this.theme === 'dark' ? '#101923' : '#ffffff';
  }
}

/** The section body as plain text — its line groups only, no heading. */
function extractSectionBodyText(section: unknown): string {
  const lineGroups = Array.isArray((section as any)?.lineGroups)
    ? (section as any).lineGroups
    : [];
  const lines: string[] = lineGroups.flatMap((group: unknown) =>
    Array.isArray(group) && group.length
      ? group.map((line) => String(line ?? ''))
      : [''],
  );
  let start = 0;
  let end = lines.length;
  while (start < end && !String(lines[start] ?? '').trim()) {
    start += 1;
  }
  while (end > start && !String(lines[end - 1] ?? '').trim()) {
    end -= 1;
  }
  return lines.slice(start, end).join('\n');
}

/** Mount a node far off-screen so it lays out for rasterization. */
function mountOffscreen(node: HTMLElement): HTMLElement {
  const stage = document.createElement('div');
  stage.style.position = 'fixed';
  stage.style.left = '-100000px';
  stage.style.top = '0';
  stage.style.opacity = '0';
  stage.style.pointerEvents = 'none';
  stage.style.contain = 'layout style paint';
  stage.append(node);
  document.body.append(stage);
  return stage;
}

/**
 * Wait for the document's web fonts to finish loading before rasterizing, so
 * the image never captures a fallback-font flash (matters most for Khmer).
 */
async function waitForDocumentFonts(): Promise<void> {
  const fonts = document.fonts;
  if (!fonts?.ready || typeof fonts.ready.then !== 'function') {
    return;
  }
  try {
    await fonts.ready;
  } catch {
    // Continue with whatever fonts are available.
  }
}

/** Whether a CSS colour is empty, `transparent`, or fully transparent rgba. */
function isTransparentColor(color: string): boolean {
  const normalized = String(color ?? '')
    .trim()
    .toLowerCase();
  if (!normalized || normalized === 'transparent') {
    return true;
  }
  const rgbaMatch = normalized.match(/^rgba?\(([^)]+)\)$/);
  if (rgbaMatch) {
    const parts = rgbaMatch[1].split(',').map((part) => part.trim());
    if (parts.length === 4 && Number.parseFloat(parts[3]) === 0) {
      return true;
    }
  }
  return false;
}
