import {
  OPEN_LYRIC_PLUGIN_API_VERSION,
  type OpenLyricComponentHost,
  type OpenLyricPlugin,
  type OpenLyricRenderContext,
  type OpenLyricRendererTargetSpec,
  type OpenLyricStyleContribution,
  type OpenLyricSurface,
  type OpenLyricTheme,
} from './types.ts';

interface PluginRecord {
  plugin: OpenLyricPlugin;
  styleNodes: HTMLElement[];
  stylesInstalled: boolean;
}

/** Contribution kinds of which a component accepts at most one plugin. */
const SINGLETON_KINDS = ['transcript', 'notation'] as const;

/**
 * Accessors the host component gives the plugin host, so the host stays
 * decoupled from the concrete component implementation.
 */
export interface PluginHostContext {
  getSurface(): OpenLyricSurface;
  /** The read-only host view passed to every plugin method. */
  readonly host: OpenLyricComponentHost;
  getContainer(): HTMLElement | null;
  /**
   * Where plugin style nodes are installed. Defaults to the container; an
   * adopt-mode component redirects to `document.head` because its container
   * is host-owned content whose `innerHTML` the render pipeline replaces
   * (and whose emptiness hosts inspect — e.g. export availability).
   */
  getStyleHost(): HTMLElement | null;
  isMounted(): boolean;
  emitPluginChange(type: 'added' | 'removed', id: string): void;
  /** Map a renderer contribution `target` to this surface's rendered DOM. */
  resolveRendererTarget(target: string): OpenLyricRendererTargetSpec | null;
  /** Ask the component to re-render (renderer contributions changed). */
  requestRender(): void;
}

function normalizeStyleContributions(
  style: OpenLyricStyleContribution | OpenLyricStyleContribution[] | undefined,
): OpenLyricStyleContribution[] {
  if (!style) {
    return [];
  }

  const entries = Array.isArray(style) ? style : [style];
  return entries.filter((entry): entry is OpenLyricStyleContribution => {
    return Boolean(entry && (entry.href || entry.cssText));
  });
}

/**
 * Per-component plugin manager. Enforces the redesign's attach rules
 * (surfaces, apiVersion, duplicate ids), installs a plugin's scoped `style`
 * contribution into the host container only while mounted, and fans the
 * lifecycle hooks (mount/unmount/value/theme) out to attached plugins.
 *
 * Style scoping today is by locality: nodes live inside the component
 * container and are torn down on unmount/detach/destroy, so nothing leaks
 * into `document.head` and nothing survives teardown.
 */
export class PluginHost {
  private readonly context: PluginHostContext;
  private readonly records = new Map<string, PluginRecord>();

  constructor(context: PluginHostContext) {
    this.context = context;
  }

  get ids(): string[] {
    return Array.from(this.records.keys());
  }

  has(id: string): boolean {
    return this.records.has(String(id));
  }

  /** The attached plugin instances, in attach order. */
  get plugins(): OpenLyricPlugin[] {
    return Array.from(this.records.values(), (record) => record.plugin);
  }

  get(id: string): OpenLyricPlugin | null {
    return this.records.get(String(id))?.plugin ?? null;
  }

  /**
   * Every attached plugin's contribution for one kind, in attach order —
   * how surface chrome discovers what its composition provides (a notation
   * plugin's `Format`, a language plugin's keyboard/spellcheck, …) without
   * hard-coding plugin ids.
   */
  collectContributions<T = unknown>(kind: string): T[] {
    const contributions: T[] = [];
    for (const record of this.records.values()) {
      const contribution = record.plugin.contributes?.[kind];
      if (contribution) {
        contributions.push(contribution as T);
      }
    }
    return contributions;
  }

  /**
   * Attach a plugin. Validation (id / apiVersion / surface / duplicate) is
   * synchronous so misconfiguration surfaces immediately. A plugin whose
   * `install()` returns a promise finishes wiring asynchronously; if it
   * rejects, the plugin is rolled back and nothing is emitted.
   */
  add(id: string, plugin: OpenLyricPlugin): void {
    const pluginId = String(id ?? '').trim();
    if (!pluginId) {
      throw new Error('addPlugin(id, plugin): a non-empty id is required.');
    }
    if (!plugin || typeof plugin !== 'object') {
      throw new TypeError('addPlugin(id, plugin): plugin must be an object.');
    }
    if (this.records.has(pluginId)) {
      throw new Error(`Plugin "${pluginId}" is already attached.`);
    }

    const apiVersion = plugin.apiVersion ?? OPEN_LYRIC_PLUGIN_API_VERSION;
    if (apiVersion !== OPEN_LYRIC_PLUGIN_API_VERSION) {
      throw new Error(
        `Plugin "${pluginId}" targets API v${apiVersion}, host supports v${OPEN_LYRIC_PLUGIN_API_VERSION}.`,
      );
    }

    if (
      Array.isArray(plugin.surfaces) &&
      plugin.surfaces.length &&
      !plugin.surfaces.includes(this.context.getSurface())
    ) {
      throw new Error(
        `Plugin "${pluginId}" does not declare the "${this.context.getSurface()}" surface.`,
      );
    }

    this.assertContributionRules(pluginId, plugin);

    const record: PluginRecord = {
      plugin,
      styleNodes: [],
      stylesInstalled: false,
    };
    this.records.set(pluginId, record);

    const finishAttach = () => {
      // A plugin removed again before an async install settled: bail out.
      if (this.records.get(pluginId) !== record) {
        return;
      }
      if (this.context.isMounted()) {
        this.installStyles(record);
        this.safe(() => record.plugin.onMount?.(this.context.host), pluginId);
        if (this.hasRenderers(plugin)) {
          this.context.requestRender();
        }
      }
      this.context.emitPluginChange('added', pluginId);
    };

    let installResult: void | Promise<void>;
    try {
      installResult = plugin.install?.(this.context.host);
    } catch (error) {
      this.records.delete(pluginId);
      throw error;
    }

    if (
      installResult &&
      typeof (installResult as Promise<void>).then === 'function'
    ) {
      (installResult as Promise<void>).then(finishAttach).catch((error) => {
        this.records.delete(pluginId);
        console.error(`Open Lyric plugin "${pluginId}" install failed.`, error);
      });
      return;
    }

    finishAttach();
  }

  remove(id: string): boolean {
    const pluginId = String(id ?? '').trim();
    const record = this.records.get(pluginId);
    if (!record) {
      return false;
    }

    if (this.context.isMounted()) {
      this.safe(() => record.plugin.onUnmount?.(this.context.host), pluginId);
    }
    this.teardownStyles(record);
    this.safe(() => record.plugin.uninstall?.(this.context.host), pluginId);

    this.records.delete(pluginId);
    // A re-render drops whatever the removed plugin's renderers drew.
    if (this.context.isMounted() && this.hasRenderers(record.plugin)) {
      this.context.requestRender();
    }
    this.context.emitPluginChange('removed', pluginId);
    return true;
  }

  /** Called from the component's `mount()`. */
  handleMount(): void {
    for (const [id, record] of this.records) {
      this.installStyles(record);
      this.safe(() => record.plugin.onMount?.(this.context.host), id);
    }
  }

  /** Called from the component's `unmount()`. */
  handleUnmount(): void {
    for (const [id, record] of this.records) {
      this.safe(() => record.plugin.onUnmount?.(this.context.host), id);
      this.teardownStyles(record);
    }
  }

  handleValueChange(oldValue: string, newValue: string): void {
    for (const [id, record] of this.records) {
      this.safe(
        () =>
          record.plugin.onValueChange?.(this.context.host, oldValue, newValue),
        id,
      );
    }
  }

  handleThemeChange(theme: OpenLyricTheme): void {
    for (const [id, record] of this.records) {
      this.safe(
        () => record.plugin.onThemeChange?.(this.context.host, theme),
        id,
      );
    }
  }

  handleBeforeRender(context: OpenLyricRenderContext): void {
    for (const [id, record] of this.records) {
      this.safe(
        () => record.plugin.onBeforeRender?.(this.context.host, context),
        id,
      );
    }
  }

  /** Fan out `onAfterRender`, then apply `renderers` contributions to the
   * freshly rendered DOM (each render pass starts from clean markup). */
  handleAfterRender(context: OpenLyricRenderContext): void {
    for (const [id, record] of this.records) {
      // Re-attach style nodes a host DOM rewrite may have disconnected.
      if (record.stylesInstalled) {
        for (const node of record.styleNodes) {
          if (!node.isConnected) {
            this.context.getStyleHost()?.append(node);
          }
        }
      }

      this.safe(
        () => record.plugin.onAfterRender?.(this.context.host, context),
        id,
      );

      const renderers = record.plugin.contributes?.renderers;
      if (!Array.isArray(renderers)) {
        continue;
      }
      for (const renderer of renderers) {
        if (!renderer || typeof renderer.render !== 'function') {
          continue;
        }
        // Targets are surface-specific; a target this surface does not
        // provide (e.g. `key-note` on markdown) is skipped, not an error.
        const spec = this.context.resolveRendererTarget(renderer.target);
        if (!spec) {
          continue;
        }
        for (const element of Array.from(
          context.root.querySelectorAll<HTMLElement>(spec.selector),
        )) {
          this.safe(() => renderer.render(spec.getText(element), element), id);
        }
      }
    }
  }

  /** Called from the component's `destroy()`. Detaches every plugin quietly. */
  destroyAll(): void {
    for (const [id, record] of this.records) {
      if (this.context.isMounted()) {
        this.safe(() => record.plugin.onUnmount?.(this.context.host), id);
      }
      this.teardownStyles(record);
      this.safe(() => record.plugin.uninstall?.(this.context.host), id);
    }
    this.records.clear();
  }

  /**
   * The redesign's conflict & uniqueness rules, enforced per component:
   * singleton kinds (`transcript`, `notation`), reserved built-in `en`
   * spellcheck, and duplicate spellcheck/keyboard keys across attached
   * plugins. Runs before the plugin is recorded, so a violation leaves the
   * host untouched.
   */
  private assertContributionRules(
    pluginId: string,
    plugin: OpenLyricPlugin,
  ): void {
    const contributes = plugin.contributes;
    if (!contributes) {
      return;
    }

    for (const kind of SINGLETON_KINDS) {
      if (!contributes[kind]) {
        continue;
      }
      for (const [otherId, other] of this.records) {
        if (other.plugin.contributes?.[kind]) {
          throw new Error(
            `Plugin "${pluginId}": at most one "${kind}" plugin may be attached; "${otherId}" already provides it.`,
          );
        }
      }
    }

    const language = contributes.language;
    if (!language) {
      return;
    }
    const spellcheckCode = language.spellcheck?.languageCode;
    if (spellcheckCode && spellcheckCode.trim().toLowerCase() === 'en') {
      throw new Error(
        `Plugin "${pluginId}": "en" spellcheck is built in and cannot be overridden.`,
      );
    }
    const keyboardId = language.keyboard?.id;
    for (const [otherId, other] of this.records) {
      const otherLanguage = other.plugin.contributes?.language;
      if (!otherLanguage) {
        continue;
      }
      if (
        spellcheckCode &&
        otherLanguage.spellcheck?.languageCode === spellcheckCode
      ) {
        throw new Error(
          `Plugin "${pluginId}": spellcheck "${spellcheckCode}" is already attached via "${otherId}".`,
        );
      }
      if (keyboardId && otherLanguage.keyboard?.id === keyboardId) {
        throw new Error(
          `Plugin "${pluginId}": keyboard "${keyboardId}" is already attached via "${otherId}".`,
        );
      }
    }
  }

  private hasRenderers(plugin: OpenLyricPlugin): boolean {
    const renderers = plugin.contributes?.renderers;
    return Array.isArray(renderers) && renderers.length > 0;
  }

  private installStyles(record: PluginRecord): void {
    if (record.stylesInstalled) {
      return;
    }
    const styleHost = this.context.getStyleHost();
    if (!styleHost) {
      return;
    }

    const entries = normalizeStyleContributions(
      record.plugin.contributes?.style,
    );
    for (const entry of entries) {
      const node = entry.href
        ? Object.assign(document.createElement('link'), {
            rel: 'stylesheet',
            href: entry.href,
          })
        : Object.assign(document.createElement('style'), {
            textContent: entry.cssText ?? '',
          });
      if (entry.media) {
        (node as HTMLLinkElement | HTMLStyleElement).media = entry.media;
      }
      node.dataset.openLyricPluginId = record.plugin.id;
      styleHost.append(node);
      record.styleNodes.push(node);
    }
    record.stylesInstalled = true;
  }

  private teardownStyles(record: PluginRecord): void {
    for (const node of record.styleNodes) {
      node.remove();
    }
    record.styleNodes = [];
    record.stylesInstalled = false;
  }

  private safe(run: () => void, pluginId: string): void {
    try {
      run();
    } catch (error) {
      console.error(`Open Lyric plugin "${pluginId}" hook failed.`, error);
    }
  }
}
