// The Open Lyric song-view render styles. This sheet is also injected verbatim
// into `document.head` by the preview components (`internal/preview-styles.ts`)
// so a bare embed needs no stylesheet import, which is why the render rules
// stay unnested: they must match the component's own `.ol-preview-root` as well
// as the app page's `[data-ol-ref="openLyricPreview"]`. They carry their own namespace
// already — `.ol-song-view*`, `.ol-preview-*`, `.open-lyric-render-surface`.
//
// The settings-popup controls below are the exception: they are chrome, in the
// shared `.topbar-settings__*` namespace, so they are scoped to the two places
// that render them — the app page's `OpenLyric` panel and the standalone
// preview chrome.

@use '../../../styles/scopes' as *;
@use 'theme-variants' as *;

// The palette. Light is the default; the dark variant follows either the
// page's `<html data-theme="dark">` (the app pages) **or** a component's own
// `[data-ol-theme='dark']` marker, so a standalone embed themes itself even on
// a host page that never set an `<html data-theme>`. The light re-assert is
// what makes the reverse work: a light embed inside a dark page (these are
// inherited custom properties, so the closest marker wins for its subtree).
:root {
  @include ol-preview-theme-tokens-light;
}

:root[data-theme='dark'],
[data-ol-theme='dark'] {
  @include ol-preview-theme-tokens-dark;
}

[data-ol-theme='light'] {
  @include ol-preview-theme-tokens-light;
}

// Settings-popup controls the Open Lyric preview contributes. Scoped to the
// two surfaces that render them: the app page panel and the standalone chrome.
@include ol-scope-lyric-surfaces {
  .topbar-settings__open-lyric-controls {
    display: grid;
    gap: 0.5rem;
  }

  .topbar-settings__open-lyric-row {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.45rem;
  }

  .topbar-settings__open-lyric-row--wrap {
    gap: 0.35rem;
  }

  .topbar-settings__open-lyric-toggle-group {
    width: 100%;
    max-width: 100%;
  }

  .topbar-settings__open-lyric-toggle-group
    > .topbar-settings__open-lyric-toggle-btn {
    --bs-btn-color: var(--heading);
    --bs-btn-bg: transparent;
    --bs-btn-border-color: var(--preview-ol-border-current);
    --bs-btn-hover-color: var(--preview-ol-accent-current);
    --bs-btn-hover-bg: color-mix(
      in srgb,
      var(--preview-ol-accent-current) 10%,
      transparent
    );
    --bs-btn-hover-border-color: var(--preview-ol-accent-current);
    --bs-btn-active-color: var(--preview-ol-accent-current);
    --bs-btn-active-bg: color-mix(
      in srgb,
      var(--preview-ol-accent-current) 16%,
      transparent
    );
    --bs-btn-active-border-color: var(--preview-ol-accent-current);
    --bs-btn-focus-shadow-rgb: 17, 94, 89;
    flex: 1 1 0;
    min-width: 0;
    font-size: 0.78rem;
    font-weight: 600;
    line-height: 1.15;
    white-space: nowrap;
  }

  .topbar-settings__open-lyric-toggle-group
    > .topbar-settings__open-lyric-toggle-btn[aria-pressed='true'] {
    --bs-btn-color: var(--preview-ol-accent-current);
    --bs-btn-bg: color-mix(
      in srgb,
      var(--preview-ol-accent-current) 18%,
      transparent
    );
    --bs-btn-border-color: var(--preview-ol-accent-current);
    --bs-btn-hover-color: var(--preview-ol-accent-current);
    --bs-btn-hover-bg: color-mix(
      in srgb,
      var(--preview-ol-accent-current) 22%,
      transparent
    );
    --bs-btn-hover-border-color: var(--preview-ol-accent-current);
  }

  .topbar-settings__structure-label {
    color: var(--muted);
    font-size: 0.78rem;
    font-weight: 600;
  }

  .topbar-settings__structure-key-control {
    flex-wrap: wrap;
  }
}

// The lyric render root on the app page — `OpenLyric`'s own element, so scoped
// to its panel. The off-screen export/print surface below carries the same
// rules unscoped: `export-surface.ts` attaches it outside the panel (and the
// standalone chrome reuses the class for printing), so no scope can reach it.
// It is already namespaced by its `open-lyric-` prefix.
@include ol-scope-lyric {
  [data-ol-ref='openLyricPreview'] {
    flex: 1 1 auto;
    height: auto;
    min-height: 0;
    padding: 1.25rem;
    line-height: 1.6;
    color: var(--ink);
    overflow: auto;
    overscroll-behavior: contain;
  }

  [data-ol-ref='openLyricPreview'] > :first-child {
    margin-top: 0;
  }

  [data-ol-ref='openLyricPreview'] > :last-child {
    margin-bottom: 0;
  }

  [data-ol-ref='openLyricPreview'] > * {
    box-sizing: border-box;
    width: fit-content;
  }

  [data-ol-ref='openLyricPreview'] a {
    color: var(--accent);
  }

  [data-ol-ref='openLyricPreview'] h1,
  [data-ol-ref='openLyricPreview'] h2,
  [data-ol-ref='openLyricPreview'] h3 {
    margin-top: 0.25rem;
    color: var(--heading);
  }

  [data-ol-ref='openLyricPreview'] pre {
    background: var(--preview-code-bg);
    border: 1px solid var(--preview-code-border);
    border-radius: 0.5rem;
    padding: 0.75rem;
    overflow: auto;
  }
}

.open-lyric-render-surface {
  height: auto;
  max-height: none;
  padding: 1.25rem;
  line-height: 1.6;
  color: var(--ink);
  overflow: visible;
}

.open-lyric-render-surface > :first-child {
  margin-top: 0;
}

.open-lyric-render-surface > :last-child {
  margin-bottom: 0;
}

.open-lyric-render-surface a {
  color: var(--accent);
}

.open-lyric-render-surface h1,
.open-lyric-render-surface h2,
.open-lyric-render-surface h3 {
  margin-top: 0.25rem;
  color: var(--heading);
}

.open-lyric-render-surface pre {
  background: var(--preview-code-bg);
  border: 1px solid var(--preview-code-border);
  border-radius: 0.5rem;
  padding: 0.75rem;
  overflow: auto;
}

.ol-song-view {
  display: grid;
  gap: 1.15rem;
  width: 100%;
}

.ol-song-view__header {
  display: grid;
  gap: 0.85rem;
  padding-bottom: 0.25rem;
}

.ol-song-view__headline {
  display: grid;
  gap: 0.2rem;
}

.ol-song-view__header-meta {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 17rem), 1fr));
