.ol-song-view__pattern-guide-cell--break {
  border-left: 1px solid var(--song-view-pattern-divider);
}

.ol-song-view__pattern-cell {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 1.25rem;
  font-size: 0.8rem;
  line-height: 1;
  color: var(--song-view-pattern-ink);
  user-select: none;
}

.ol-song-view__pattern-cell-button {
  appearance: none;
  width: 100%;
  padding: 0;
  border: none;
  background: transparent;
  color: inherit;
  font: inherit;
  cursor: pointer;
}

.ol-song-view__pattern-cell-button:hover {
  text-shadow: 0 0 4px var(--accent);
}

.ol-song-view__pattern-cell-button:focus-visible {
  outline: none;
  box-shadow: inset 0 0 0 2px var(--accent-halo);
}

.ol-song-view__pattern-cell--accent {
  color: var(--song-view-chord);
  font-size: 0.75rem;
  font-weight: 700;
}

.ol-song-view__pattern-cell--stroke {
  min-height: 0.6rem;
  font-size: 1.1rem;
}

.ol-song-view__pattern-cell--down,
.ol-song-view__pattern-cell--up {
  color: var(--song-view-pattern-ink);
}

.ol-song-view__pattern-cell--rest {
  color: transparent;
}

.ol-song-view__pattern-cell--break {
  border-left: 1px solid var(--song-view-pattern-divider);
}

.ol-song-view__structures {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  gap: 0.65rem;
}

.ol-song-view__structure {
  width: 100%;
  border: 1px solid var(--preview-ol-border-current);
  border-radius: 0.85rem;
  background: var(--surface-elevated, var(--surface));
  overflow: hidden;
}

.ol-song-view__structure-actions {
  display: flex;
  flex: 0 1 auto;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-end;
  gap: 0.35rem;
  min-width: 0;
  max-width: 100%;
  margin-left: auto;
}

.ol-song-view__structure-key-control {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  color: var(--song-view-muted);
}

.ol-song-view__structure-key-step,
.ol-song-view__structure-key-select {
  border: 1px solid var(--preview-ol-border-current);
  background: var(--surface);
  color: var(--heading);
  font: inherit;
  font-weight: 700;
}

.ol-song-view__structure-key-step {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 2rem;
  height: 2rem;
  padding: 0;
  border-radius: 999px;
  cursor: pointer;
}

.ol-song-view__structure-key-select {
  padding: 0 0.35rem;
  border-radius: 999px;
  font-size: 0.88rem;
  cursor: pointer;
}

.ol-song-view__structure-key-step:hover,
.ol-song-view__structure-key-select:hover {
  border-color: var(--preview-ol-accent-current);
}

.ol-song-view__structure-key-step:focus-visible,
.ol-song-view__structure-key-select:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px var(--accent-halo);
}

.ol-song-view__simplify-toggle {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  min-height: 1.85rem;
  padding: 0 0.6rem;
  border: 1px solid var(--preview-ol-border-current);
  border-radius: 999px;
  background: var(--surface);
  color: var(--heading);
  font: inherit;
  font-size: 0.82rem;
  font-weight: 600;
  cursor: pointer;
}

.ol-song-view__simplify-toggle:hover {
  border-color: var(--preview-ol-accent-current);
}

.ol-song-view__simplify-toggle:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px var(--accent-halo);
}

.ol-song-view__simplify-toggle-indicator {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 0.9rem;
  height: 0.9rem;
  flex: 0 0 auto;
  border: 1px solid var(--preview-ol-border-current);
  border-radius: 0.25rem;
  background: transparent;
}

.ol-song-view__simplify-toggle[aria-pressed='true'] {
  border-color: var(--preview-ol-accent-current);
  color: var(--preview-ol-accent-current);
}

.ol-song-view__simplify-toggle[aria-pressed='true']
  .ol-song-view__simplify-toggle-indicator {
  border-color: var(--preview-ol-accent-current);
  background: color-mix(
    in srgb,
    var(--preview-ol-accent-current) 18%,
    transparent
  );
}

.ol-song-view__simplify-toggle[aria-pressed='true']
  .ol-song-view__simplify-toggle-indicator::before {
  content: '\2713';
  font-size: 0.72rem;
  line-height: 1;
  color: var(--preview-ol-accent-current);
}

.ol-song-view__structure-body {
  padding: 0.35rem 0.4rem 0.5rem;
  border-top: 1px solid var(--preview-ol-border-current);
}

.ol-song-view__structure-meta {
  margin-bottom: 0.45rem;
  padding-bottom: 0.45rem;
  border-bottom: 1px solid var(--preview-ol-border-current);
}

.ol-song-view__structure-overview {
  margin-bottom: 0.45rem;
  padding-bottom: 0.45rem;
  border-bottom: 1px solid var(--preview-ol-border-current);
}

.ol-song-view__structure-overview .ol-preview-structure-line {
  gap: 0.35rem;
}

.ol-song-view__structure-overview .ol-preview-structure-link {
  gap: 0.35rem;
}

.ol-song-view__structure-overview .ol-preview-structure-step {
  padding: 0.02rem 0.35rem;
  font-size: 0.88rem;
}

.ol-song-view__sections {
  // Base width of one "block". Sections whose content would otherwise be
  // clipped are widened to span extra blocks by balanceOpenLyricSectionSpans().
  --ol-section-column: 16rem;
  display: grid;
  grid-template-columns: repeat(
    auto-fit,
    minmax(min(100%, var(--ol-section-column)), 1fr)
  );
  align-items: stretch;
  gap: 0.9rem 0.4rem;
  margin-top: 0.5rem;
}

.ol-song-view__section {
  // Allow the block to shrink to its track so overflowing lyric lines are
  // measured (and the section widened) rather than forcing the whole grid wide.
  min-width: 0;
  padding: 0.35rem;
  border-radius: 0.85rem;
  // add alpha 0.3 to the box-shadow to make it more subtle
  box-shadow: 1px 1px 2px
    color-mix(in srgb, var(--preview-ol-border-current) 20%, transparent);
}

.ol-song-view__section--missing {
  gap: 0.55rem;
}

.ol-song-view__section-line {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0.35rem;
}

.ol-song-view__section-title {
  margin: 0;
  margin-bottom: 0.55rem;
  font-size: 0.9rem;
  font-weight: 500;
  text-decoration-line: underline;
  text-decoration-color: var(--preview-ol-border-current);
  text-decoration-thickness: 0.06em;
  text-underline-offset: 0.22em;
}

@include ol-scope-lyric {
  [data-ol-ref='openLyricPreview'] .ol-song-view__section-title {
    margin-top: 0;
  }
}

.open-lyric-render-surface .ol-song-view__section-title {
  margin-top: 0;
}

.ol-song-view__section-body {
  min-width: 0;
}

.ol-song-view__section-inline-body {
  min-width: 0;
  flex: 1 1 16rem;
}

.ol-song-view__section-inline-body .ol-preview-line {
  margin-left: 0;
}

.ol-song-view .ol-preview-lines {
  font-variant-ligatures: none;
  tab-size: 4;
}

.ol-song-view__section-inline-body--text .ol-preview-lines {
  display: block;
}

.ol-song-view__repeat {
  margin-left: 0;
}

.ol-song-view__missing-note,
.ol-song-view__empty {
  padding: 1rem 1.1rem;
  border: 1px dashed var(--preview-ol-border);
  border-radius: 0.9rem;
  color: var(--preview-ol-muted);
}

.ol-preview-fence {
  margin: 1.1rem 0;
  border: 1px solid var(--preview-ol-border-current);
  border-radius: 0.9rem;
  background: var(--preview-ol-bg);
  overflow: hidden;
  scroll-margin-top: 0.85rem;
  box-shadow: 0 10px 24px rgba(16, 25, 35, 0.08);
  transition:
    box-shadow 180ms ease,
    border-color 180ms ease;
}

.ol-preview-fence--jump-target {
  box-shadow:
    0 0 0 3px var(--accent-halo),
    0 10px 24px rgba(16, 25, 35, 0.12);
}

.ol-preview-fence__summary {
  display: flex;
  align-items: center;
  gap: 0.7rem;
  padding: 0.1rem 1rem;
  background: rgba(255, 255, 255, 0.14);
  cursor: pointer;
  list-style: none;
  user-select: none;
}

.ol-preview-fence__summary::-webkit-details-marker {
  display: none;
}

.ol-preview-fence__summary::before {
  content: '';
  flex: 0 0 auto;
  width: 0.6rem;
  height: 0.6rem;
  border-right: 0.12rem solid currentColor;
  border-bottom: 0.12rem solid currentColor;
  color: var(--preview-ol-heading);
  opacity: 0.7;
  transform: translateY(-0.08rem) rotate(45deg);
  transition:
    transform 180ms ease,
    opacity 180ms ease;
}

.ol-preview-fence:not([open]) .ol-preview-fence__summary::before {
  transform: translateY(-0.02rem) rotate(-45deg);
}

.ol-preview-fence[open] .ol-preview-fence__summary {
  border-bottom: 1px solid var(--preview-ol-border-current);
}

.ol-preview-fence__summary:hover::before,
.ol-preview-fence__summary:focus-visible::before {
  opacity: 1;
}

.ol-preview-fence__summary:focus-visible {
  outline: none;
  box-shadow: inset 0 0 0 2px var(--accent-halo);
}

.ol-preview-fence__title {
  color: var(--preview-ol-heading);
  font-size: 1.05rem;
}

.ol-preview-fence__body {
  padding: 0.5rem 0.5rem 0.7rem;
}

.ol-preview-lines {
  display: grid;
  gap: 0.45rem;
}

.ol-preview-line {
  margin-left: 1rem;
  white-space: pre-wrap;
  word-break: break-word;
}

.ol-preview-line--chorded {
  white-space: normal;
  word-break: normal;
  overflow-x: auto;
  overflow-y: hidden;
  scrollbar-width: thin;
}

.ol-preview-line__content--chorded {
  display: inline-block;
  min-width: 100%;
  white-space: nowrap;
}

.ol-preview-lyric-segment {
  display: inline-grid;
  grid-template-rows: auto auto;
  vertical-align: top;
}

.ol-preview-chord {
  appearance: none;
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: 0.3rem;
  background: transparent;
  color: var(--accent);
  cursor: pointer;
  font-size: 0.7em;
  line-height: inherit;
  transition:
    background 160ms ease,
    box-shadow 160ms ease,
    color 160ms ease;
}

.ol-preview-chord--with-brackets {
  display: inline-flex;
  align-items: baseline;
  gap: 0;
}

.ol-preview-chord--hidden {
  display: none;
}

.ol-preview-chord__bracket {
  color: transparent;
  user-select: none;
}

.ol-preview-chord:hover,
.ol-preview-chord:focus-visible {
  background: var(--preview-ol-chip-bg);
  box-shadow: 0 0 0 1px var(--preview-ol-chip-border);
  color: var(--preview-ol-accent-current);
