.ol-chord-popup {
  --ol-chord-popup-pointer-x: 50%;
  --ol-chord-popup-main-diagram-width: 124px;
  --ol-chord-popup-variant-scale: 0.3;
  position: fixed;
  top: 0;
  left: 0;
  z-index: 50;
  width: min(136.5px, calc(100vw - 24px));
  padding: 0.3rem;
